--
-- Estrutura para tabela `bloco_0000`
--

DROP TABLE IF EXISTS `bloco_0000`;
CREATE TABLE IF NOT EXISTS `bloco_0000` (
  `id` int NOT NULL AUTO_INCREMENT,
  `num` varchar(10) NOT NULL COMMENT 'Nº (ordem)',
  `campo` varchar(50) NOT NULL COMMENT 'Nome do campo (ex: REG)',
  `descricao` text NOT NULL COMMENT 'Descrição do campo',
  `tipo` char(1) NOT NULL COMMENT 'Tipo (C = caractere, N = numérico, etc.)',
  `tamanho` varchar(10) DEFAULT NULL COMMENT 'Tamanho do campo (ex: 004)',
  `decimal` varchar(10) DEFAULT NULL COMMENT 'Casas decimais (se aplicável)',
  `valores_validos` varchar(255) DEFAULT NULL COMMENT 'Valores válidos (ex: "0000")',
  `obrigatorio` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = Sim, 0 = Não',
  `regras_validacao` text COMMENT 'Regras de validação do campo',
  `ocorrencia` varchar(20) DEFAULT NULL,
  `nivel_hierarquico` int DEFAULT NULL,
  `campos_chave` varchar(255) DEFAULT NULL,
  `regras_registro` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Despejando dados para a tabela `bloco_0000`
--

INSERT INTO `bloco_0000` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `ocorrencia`, `nivel_hierarquico`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"0000\".', 'C', '004', NULL, '\"0000\"', 1, NULL, '1:1', 0, '[REG]', '[REGRA_PERIODO_MINIMO_ESCRITURACAO]: Verifica, caso o campo indicador de situação especial – IND_SIT_ESP (Campo 11) – não tenha sido informado, se os campos data inicial das informações contidas no arquivo – DT_INI (Campo 03) – e data final das informações contidas no arquivo – DT_FIN (Campo 04) –\nabrange, no mínimo, um mês, ou seja, caso não exista situação especial, devem ser informados sempre meses completos (a DT_INI é o primeiro dia de um mês e a DT_FIN é o último dia do mês). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n\n[REGRA_PERIODO_MAXIMO_ESCRITURACAO]: Verifica se os campos data inicial das informações contidas no arquivo – DT_INI (Campo 03) – e data final das informações contidas no arquivo – DT_FIN (Campo 04) – estão contidos no mesmo ano. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n\n[REGRA_TAMANHO_ARQUIVO]: Verifica se o tamanho do arquivo é menor que um gigabyte (5 GB). Se for maior, verifica se o período da escrituração (campos DT_INI e DT_FIN) se refere a apenas um mês. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n\n[REGRA_OCORRENCIA_UNITARIA_ARQ]: Verifica se registro ocorreu apenas uma vez por arquivo, considerando a chave “0000” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n\n[REGRA_ERRO_ENTIDADE]: Verifique se o plano referencial informado no campo 0000.COD_PLAN_REF (Campo 23) é compatível com a entidade referencial informada no registro 0007, no campo\n0007.COD_ENT_REF, no caso do TSE (Se 0007.COD_ENT_REF = “05” (TSE), então 0000.COD_PLAN_REF deve ser igual a “9” – Partidos Políticos. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(2, '02', 'LECD', 'Texto fixo contendo \"LECD\".', 'C', '004', NULL, '\"LECD\"', 1, NULL, '1:1', 0, '[REG]', '[REGRA_PERIODO_MINIMO_ESCRITURACAO]: Verifica, caso o campo indicador de situação especial – IND_SIT_ESP (Campo 11) – não tenha sido informado, se os campos data inicial das informações contidas no arquivo – DT_INI (Campo 03) – e data final das informações contidas no arquivo – DT_FIN (Campo 04) –\r\nabrange, no mínimo, um mês, ou seja, caso não exista situação especial, devem ser informados sempre meses completos (a DT_INI é o primeiro dia de um mês e a DT_FIN é o último dia do mês). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_PERIODO_MAXIMO_ESCRITURACAO]: Verifica se os campos data inicial das informações contidas no arquivo – DT_INI (Campo 03) – e data final das informações contidas no arquivo – DT_FIN (Campo 04) – estão contidos no mesmo ano. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_TAMANHO_ARQUIVO]: Verifica se o tamanho do arquivo é menor que um gigabyte (5 GB). Se for maior, verifica se o período da escrituração (campos DT_INI e DT_FIN) se refere a apenas um mês. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OCORRENCIA_UNITARIA_ARQ]: Verifica se registro ocorreu apenas uma vez por arquivo, considerando a chave “0000” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_ERRO_ENTIDADE]: Verifique se o plano referencial informado no campo 0000.COD_PLAN_REF (Campo 23) é compatível com a entidade referencial informada no registro 0007, no campo\r\n0007.COD_ENT_REF, no caso do TSE (Se 0007.COD_ENT_REF = “05” (TSE), então 0000.COD_PLAN_REF deve ser igual a “9” – Partidos Políticos. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(3, '03', 'DT_INI', 'Data inicial das informações contidas no arquivo.', 'N', '008', NULL, NULL, 1, '[REGRA_DATA_INI_MAIOR]: Verifica se o campo DT_INI (Campo 03) foi preenchido com a data igual ou\r\nanterior à data do DT_FIN (Campo 04). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro;\r\n\r\n[REGRA_INICIO_PERIODO]: Verifica se o dia informado no campo data inicial das informações contidas no\r\narquivo – DT_INI (Campo 03) – corresponde ao primeiro dia do mês e se o campo indicador de situação no\r\ninício do período – IND_SIT_INI_PER (Campo 12) – foi informado com valor igual a zero. Se a regra não for\r\ncumprida, o PGE do Sped Contábil gera um erro.', '1:1', 0, '[REG]', '[REGRA_PERIODO_MINIMO_ESCRITURACAO]: Verifica, caso o campo indicador de situação especial – IND_SIT_ESP (Campo 11) – não tenha sido informado, se os campos data inicial das informações contidas no arquivo – DT_INI (Campo 03) – e data final das informações contidas no arquivo – DT_FIN (Campo 04) –\r\nabrange, no mínimo, um mês, ou seja, caso não exista situação especial, devem ser informados sempre meses completos (a DT_INI é o primeiro dia de um mês e a DT_FIN é o último dia do mês). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_PERIODO_MAXIMO_ESCRITURACAO]: Verifica se os campos data inicial das informações contidas no arquivo – DT_INI (Campo 03) – e data final das informações contidas no arquivo – DT_FIN (Campo 04) – estão contidos no mesmo ano. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_TAMANHO_ARQUIVO]: Verifica se o tamanho do arquivo é menor que um gigabyte (5 GB). Se for maior, verifica se o período da escrituração (campos DT_INI e DT_FIN) se refere a apenas um mês. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OCORRENCIA_UNITARIA_ARQ]: Verifica se registro ocorreu apenas uma vez por arquivo, considerando a chave “0000” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_ERRO_ENTIDADE]: Verifique se o plano referencial informado no campo 0000.COD_PLAN_REF (Campo 23) é compatível com a entidade referencial informada no registro 0007, no campo\r\n0007.COD_ENT_REF, no caso do TSE (Se 0007.COD_ENT_REF = “05” (TSE), então 0000.COD_PLAN_REF deve ser igual a “9” – Partidos Políticos. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
