  `descricao` text NOT NULL,
  `tipo` char(1) NOT NULL,
  `tamanho` varchar(10) DEFAULT NULL,
  `decimal` varchar(10) DEFAULT NULL,
  `valores_validos` varchar(255) DEFAULT NULL,
  `obrigatorio` tinyint(1) NOT NULL DEFAULT '1',
  `regras_validacao` text,
  `ocorrencia` varchar(20) DEFAULT NULL,
  `nivel_hierarquico` int DEFAULT NULL,
  `campos_chave` varchar(255) DEFAULT NULL,
  `regras_registro` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

