INSERT INTO `bloco_0001` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `ocorrencia`, `nivel_hierarquico`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"0001\".', 'C', '004', NULL, '\"0001\"', 1, NULL, '1:1', 1, '[REG]\r\n', 'REGRA_OCORRENCIA_UNITARIA_ARQ: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “0001” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
