INSERT INTO `bloco_0007` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `ocorrencia`, `nivel_hierarquico`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"0007\".', 'C', '004', NULL, '\"0007\"', 1, NULL, '1:N', 2, '', '\r\n'),
(2, '02', 'COD_ENT_REF', 'Código da instituição responsável pela administração do cadastro (conforme tabela publicada pelo Sped).', 'C', NULL, NULL, NULL, 1, '[REGRA_TABELA_INSTITUICOES_CADASTRO]: Verifica se o código informado no campo código da instituição responsável pela administração do cadastro – COD_ENT_REF (Campo 02) – existe na Tabela de\nInstituições Responsáveis pela Administração do Cadastro das Entidades. Se a regra não for cumprida, o PGE\ndo Sped Contábil gera um erro.', '1:N', 2, '', '\r\n'),
(3, '03', 'COD_INSCR', 'Código cadastral da pessoa jurídica na instituição identificada no campo 02.', 'C', NULL, NULL, NULL, 0, '[REGRA_VALIDA_INSCRICAO]: Verifica qual é a regra de formação do campo código cadastral da pessoa jurídica – COD_INSCR (Campo 03) – que deve ser aplicada, a partir do preenchimento do campo código da\ninstituição responsável pela administração do cadastro – COD_ENT_REF (Campo 02).', '1:N', 2, '', '');

