INSERT INTO `bloco_0020` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `ocorrencia`, `nivel_hierarquico`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"0020\".', 'C', '004', NULL, '\"0020\"', 1, NULL, '0:N', 2, '[IND_DEC]+[CNPJ]', '[REGRA_OCORRENCIA_0020_ARQ]: Verifica se o campo indicador de descentralização – IND_DEC (Campo 02) – é igual a “1” – “Escrituração da filial” - e se o registro 0020 ocorreu apenas uma vez no arquivo. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(2, '02', 'IND_DEC', 'Indicador de descentralização: 0 – Escrituração da matriz. 1 – Escrituração da filial.', 'N', '001', NULL, '[0,1]', 1, '[REGRA_CONGLOMERADO_NA_MATRIZ]:Verifica, quando campo indicador de descentralização – IND_DEC (Campo 02) – é igual a “1” – Escrituração da filial, se o campo indicador de escriturações contábeis consolidadas – IND_ESC_CONS (Campo 20) – do registro 0000 é diferente de “S”. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[IND_DEC]+[CNPJ]', '[REGRA_OCORRENCIA_0020_ARQ]: Verifica se o campo indicador de descentralização – IND_DEC (Campo 02) – é igual a “1” – “Escrituração da filial” - e se o registro 0020 ocorreu apenas uma vez no arquivo. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(3, '03', 'CNPJ', 'Número de inscrição da pessoa jurídica no CNPJ da matriz ou da filial.', 'N', '014', NULL, NULL, 1, '[REGRA_VALIDA_CNPJ]: Verifica se a regra de formação do CNPJ (Campo 03) é válida. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n\n[REGRA_VERIFICA_CNPJ_REG_0000_REG_0020]: Verifica se os oito primeiros dígitos do campo CNPJ\n(Campo 06) do registro 0000 são iguais aos oito primeiros dígitos do CNPJ (Campo 03) do registro 0020. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n\n[REGRA_REGISTRO_DUPLICADO]: Verifica se o registro não é duplicado, considerando os campos  chave(CNPJ e IND_DEC). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n\n[REGRA_DUPLICIDADE_CNPJ_REG_0000_REG_0020]: Verifica se o campo CNPJ (Campo 06) do registro 0000 é diferente do campo CNPJ (Campo 03) do registro 0020. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[IND_DEC]+[CNPJ]', '[REGRA_OCORRENCIA_0020_ARQ]: Verifica se o campo indicador de descentralização – IND_DEC (Campo 02) – é igual a “1” – “Escrituração da filial” - e se o registro 0020 ocorreu apenas uma vez no arquivo. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(4, '04', 'UF', 'Sigla da unidade da federação da matriz ou da filial.', 'C', '002', NULL, NULL, 1, '[REGRA_TABELA_UF]: Verifica se o código informado da Unidade da Federação - UF (Campo 04) existe\nna Tabela de Unidades da Federação. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[IND_DEC]+[CNPJ]', '[REGRA_OCORRENCIA_0020_ARQ]: Verifica se o campo indicador de descentralização – IND_DEC (Campo 02) – é igual a “1” – “Escrituração da filial” - e se o registro 0020 ocorreu apenas uma vez no arquivo. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(5, '05', 'IE', 'Inscrição estadual da matriz ou da filial.', 'C', NULL, NULL, NULL, 0, '[REGRA_CAMPO_CARACTERE_INVALIDO]: Verifica se os campos “Inscrição Estadual – IE” (Campo 05)\ne “Inscrição Municipal – IM” (Campo 7) foram preenchidos somente com letras e números. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[IND_DEC]+[CNPJ]', '[REGRA_OCORRENCIA_0020_ARQ]: Verifica se o campo indicador de descentralização – IND_DEC (Campo 02) – é igual a “1” – “Escrituração da filial” - e se o registro 0020 ocorreu apenas uma vez no arquivo. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(6, '06', 'COD_MUN', 'Código do município do domicílio da matriz ou da filial.', 'N', '007', NULL, NULL, 0, '[REGRA_TABELA_MUNICIPIO]:Verifica se o código do município informado no campo código do município do domicílio da matriz ou da filial – COD_MUN (Campo 06) – existe na tabela do IBGE. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n', '0:N', 2, '[IND_DEC]+[CNPJ]', '[REGRA_OCORRENCIA_0020_ARQ]: Verifica se o campo indicador de descentralização – IND_DEC (Campo 02) – é igual a “1” – “Escrituração da filial” - e se o registro 0020 ocorreu apenas uma vez no arquivo. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(7, '07', 'IM', 'Número de Inscrição Municipal da matriz ou da filial.', 'C', NULL, NULL, NULL, 0, '[REGRA_CAMPO_CARACTERE_INVALIDO]: Verifica se os campos “Inscrição Estadual – IE” (Campo 05)\ne “Inscrição Municipal – IM” (Campo 7) foram preenchidos somente com letras e números. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[IND_DEC]+[CNPJ]', '[REGRA_OCORRENCIA_0020_ARQ]: Verifica se o campo indicador de descentralização – IND_DEC (Campo 02) – é igual a “1” – “Escrituração da filial” - e se o registro 0020 ocorreu apenas uma vez no arquivo. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(8, '08', 'NIRE', 'Número de Identificação do Registro de Empresas da matriz ou da filial na Junta Comercial.', 'N', '11', NULL, NULL, 0, '[REGRA_VALIDA_NIRE]: Verifica se a regra de formação do campo NIRE é válida. Se a regra não for\ncumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[IND_DEC]+[CNPJ]', '[REGRA_OCORRENCIA_0020_ARQ]: Verifica se o campo indicador de descentralização – IND_DEC (Campo 02) – é igual a “1” – “Escrituração da filial” - e se o registro 0020 ocorreu apenas uma vez no arquivo. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');

