(1, '01', 'REG', 'Texto fixo contendo \"0150\".', 'C', '004', NULL, '\"0150\"', 1, NULL, '0:N', 2, '[COD_PART]\r\n', ''),
(2, '02', 'COD_PART', 'Código de identificação do participante no arquivo criado pela própria pessoa jurídica.', 'C', NULL, NULL, NULL, 1, '[REGRA_REGISTRO_DUPLICADO]: Verifica se o registro não é duplicado, considerando o campo código\nde identificação do participante – COD_PART (Campo 02) – especificado para o registro. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n', '0:N', 2, '[COD_PART]\r\n', ''),
(3, '03', 'NOME', 'Nome pessoal ou empresarial do participante.', 'C', NULL, NULL, NULL, 1, NULL, '0:N', 2, '[COD_PART]\r\n', ''),
(4, '04', 'COD_PAIS', 'Código do país do participante, conforme a tabela do Banco Central do Brasil.', 'N', '005', NULL, NULL, 1, '[REGRA_TABELA_PAIS]: Verifica se o código do país informado (Campo 04) existe na Tabela de Código do País Participante. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[COD_PART]\r\n', ''),
(5, '05', 'CNPJ', 'CNPJ do participante.', 'N', '014', NULL, NULL, 0, '[REGRA_VALIDA_CNPJ]: Verifica se a regra de formação do CNPJ (Campo 05) é válida. Se a regra não for\ncumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[COD_PART]\r\n', ''),
(6, '06', 'CPF', 'CPF do participante.', 'N', '011', NULL, NULL, 0, '[REGRA_VALIDA_CPF]: Verifica se a regra de formação do CPF (Campo 06) é válida. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n', '0:N', 2, '[COD_PART]\r\n', ''),
(7, '07', 'NIT', 'Número de Identificação do Trabalhador, Pis, Pasep, SUS.', 'N', '011', NULL, NULL, 0, NULL, '0:N', 2, '[COD_PART]\r\n', ''),
(8, '08', 'UF', 'Sigla da unidade da federação do participante.', 'C', '002', NULL, NULL, 0, '[REGRA_TABELA_UF]: Verifica se o código informado da Unidade da Federação - UF (Campo 08) existe\nna Tabela de Unidades da Federação. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n\n[REGRA_CAMPO_NAO_OBRIGATORIO_PAIS_BRASIL]: Verifica se a UF (Campo 08) não foi preenchida, no caso de países diferentes do Brasil. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n', '0:N', 2, '[COD_PART]\r\n', ''),
(9, '09', 'IE', 'Inscrição Estadual do participante.', 'C', NULL, NULL, NULL, 0, '[REGRA_CAMPO_CARACTERE_INVALIDO]: Verifica se o campo “Inscrição Estadual – IE” (Campo 09) foi preenchido somente com letras e números. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[COD_PART]\r\n', ''),
(10, '10', 'IE_ST', 'Inscrição Estadual do participante na unidade da federação do destinatário, na condição de contribuinte substituto.', 'C', NULL, NULL, NULL, 0, '[REGRA_CAMPO_CARACTERE_INVALIDO]: Verifica se o campo “Inscrição Estadual do participante na\nunidade da federação do destinatário, na condição de contribuinte substituto – IE_ST” (Campo 10), “Inscrição Municipal – IM” (Campo 12) e “Suframa” (Campo 13) foram preenchidos somente com letras e números. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[COD_PART]\r\n', ''),
(11, '11', 'COD_MUN', 'Código do município, conforme a tabela do IBGE.', 'N', '007', NULL, NULL, 0, '[REGRA_TABELA_MUNICIPIO]:Verifica se o código do município informado no campo COD_MUN (Campo 11) existe na tabela do IBGE. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n\n[REGRA_CAMPO_NAO_OBRIGATORIO_PAIS_BRASIL]: Verifica se o COD_MUN (Campo 11) não foi preenchido, no caso de países diferentes do Brasil. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[COD_PART]\r\n', ''),
(12, '12', 'IM', 'Inscrição Municipal do participante.', 'C', NULL, NULL, NULL, 0, '[REGRA_CAMPO_CARACTERE_INVALIDO]: Verifica se o campo “Inscrição Estadual do participante na\nunidade da federação do destinatário, na condição de contribuinte substituto – IE_ST” (Campo 10), “Inscrição Municipal – IM” (Campo 12) e “Suframa” (Campo 13) foram preenchidos somente com letras e números. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[COD_PART]\r\n', ''),
(13, '13', 'SUFRAMA', 'Número de inscrição do participante na Suframa.', 'C', '009', NULL, NULL, 0, '[REGRA_CAMPO_CARACTERE_INVALIDO]: Verifica se o campo “Inscrição Estadual do participante na\nunidade da federação do destinatário, na condição de contribuinte substituto – IE_ST” (Campo 10), “Inscrição Municipal – IM” (Campo 12) e “Suframa” (Campo 13) foram preenchidos somente com letras e números. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '0:N', 2, '[COD_PART]\r\n', '');

