INSERT INTO `bloco_9900` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `ocorrencia`, `nivel_hierarquico`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"9900\".', 'C', '4', NULL, '\"9900\"', 1, NULL, '0:N', 2, '[REG_BLC]', '[REGRA_QTD_REG_BLC_OBRIGATORIO]:Verifica se todos os tipos de registros existentes no arquivo foram totalizados no registro 9900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_REG_BLC_DUPLICIDADE]:Verifica se o registro não é duplicado considerando a chave registro que será totalizado – “REG_BLC” (Campo 02). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n'),
(2, '02', 'REG_BLC', 'Registro que será\ntotalizado no\npróximo campo.\n', 'C', '4', NULL, 'Somente\ntipos de\nregistro\nprevistos\npara a\nescrituração\ncontábil\ndigital.\n', 1, NULL, '0:N', 2, '[REG_BLC]', '[REGRA_QTD_REG_BLC_OBRIGATORIO]:Verifica se todos os tipos de registros existentes no arquivo foram totalizados no registro 9900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_REG_BLC_DUPLICIDADE]:Verifica se o registro não é duplicado considerando a chave registro que será totalizado – “REG_BLC” (Campo 02). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n'),
(3, '03', 'QTD_REG_BLC ', 'Total de registros\ndo tipo informado\nno campo anterior.', 'N', NULL, NULL, NULL, 1, '[REGRA_QTD_REG_BLC]: Verifica se o número de linhas do arquivo, por tipo de registro, é igual ao valor\r\ninformado no total de registros do tipo informado no campo registro que será totalizado – QTD_REG_BLC\r\n(Campo 03). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n', '1:N', 2, '[REG_BLC]', '[REGRA_QTD_REG_BLC_OBRIGATORIO]:Verifica se todos os tipos de registros existentes no arquivo foram totalizados no registro 9900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_REG_BLC_DUPLICIDADE]:Verifica se o registro não é duplicado considerando a chave registro que será totalizado – “REG_BLC” (Campo 02). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n');

