INSERT INTO `bloco_c155` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal_places`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"C155\".', 'C', '004', NULL, '\"C155\"', 1, NULL, 4, '1:N', '[COD_CTA_REC]+[COD_CCUS_REC]', '[REGRA_CONTA_C155_INEXISTENTE_I155]:\r\nVerifica, quando:\r\n0000.IND_MUDANCA_PC = “0” (não houve mudança de plano de contas); e a data do encerramento do exercício social informada no registro I030 (I030.DT_EX_SOCIAL) é diferente de 31/12; e a natureza (C050.COD_NAT) da conta/centros de custos do registro C155 (C155.COD_CTA/C155.COD.CCUS) é igual a “01” (ativo), “02” (passivo), “03” (patrimônio líquido) ou “04” (contas de resultado) e C155.VL_SLD_FIN é diferente de zero, se existe a mesma conta/centro de custos no registro I155; ou\r\nA data do encerramento do exercício social informada no registro I030 (I030.DT_EX_SOCIAL) é igual a 31/12; e a natureza (C050.COD_NAT) da conta do registro C155 (C155.COD_CTA) é igual a “04” (contas de resultado) e C155.VL_SLD_FIN é diferente de zero, se existe a mesma conta/centro de custos no registro I155;\r\nou\r\nA data do encerramento do exercício social informada no registro I030 (I030.DT_EX_SOCIAL) é igual a 31/12; e a natureza (C050.COD_NAT) da conta/centros de custos do registro C155 (C155.COD_CTA/C155.COD.CCUS) é igual a “01” (ativo), “02” (passivo) ou “03” (patrimônio líquido) e C155.VL_SLD_FIN é diferente de zero, se existe a mesma conta/centro de custos no registro I155;\r\nou\r\n0000.IND_MUDANCA_PC = “1” (houve mudança de plano de contas); e a data do encerramento do exercício social informada no registro I030 (I030.DT_EX_SOCIAL) é diferente de 31/12; e a natureza (C050.COD_NAT) da conta/centros de custos do registro C155 (C155.COD_CTA/C155.COD.CCUS) é igual a “01” (ativo), “02” (passivo), “03” (patrimônio líquido) ou “04” (contas de resultado) e C155.VL_SLD_FIN é diferente de zero, se existe o registro I155 e o registro I157 relacionado para a mesma conta/centro de custos.\r\nSe a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_NATUREZA_CONTA_C155]:\r\nVerifica se a natureza da conta/centro de custos (C050.COD_NAT) informada no registro C155 é igual à natureza da mesma conta/centro (I050_COD_NAT) informada no registro I155. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
