INSERT INTO `bloco_i010` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I010\".', 'C', '004', NULL, '\"I010\"', 1, NULL, 2, '1:1', '[REG]', '[REGRA_OCORRENCIA_UNITARIA_ARQ]: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I010” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(2, '02', 'IND_ESC', 'Indicador da forma de escrituração contábil: G - Livro Diário (Completo sem escrituração auxiliar); R - Livro Diário com Escrituração Resumida (com escrituração auxiliar); A - Livro Diário Auxiliar ao Diário com Escrituração Resumida; B - Livro Balancetes Diários e Balanços; Z - Razão Auxiliar (Livro Contábil Auxiliar conforme leiaute definido nos registros I500 a I555).', 'C', '001', NULL, '[\"G\",\"R\",\"A\",\"B\",\"Z\"]', 1, NULL, 2, '1:1', '[REG]', '[REGRA_OCORRENCIA_UNITARIA_ARQ]: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I010” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(3, '03', 'COD_VER_LC', 'Código da Versão do Leiaute Contábil.', 'C', NULL, NULL, '[9.00]', 1, '[REGRA_VERSAO_LC]: Verifica se a versão do leiaute informada é válida. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 2, '1:1', '[REG]', '[REGRA_OCORRENCIA_UNITARIA_ARQ]: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I010” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');

