--
-- Despejando dados para a tabela `bloco_i012`
--

INSERT INTO `bloco_i012` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I012\".', 'C', '004', NULL, '\"I012\"', 1, NULL, 3, '1:N', NULL, '[REGRA_OCORRENCIA_UNITARIA_I012]: Verifica se o registro ocorreu apenas uma vez por arquivo, no caso de o tipo da escrituração ser “A” ou “Z”. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n'),
(2, '02', 'NUM_ORD', 'Número de ordem do livro auxiliar vinculado ao principal.', 'C', '003', NULL, NULL, 1, '[REGRA_MAIOR_QUE_ZERO]: Verifica se o campo número de ordem do instrumento associado – a NUM_ORD (Campo 02) – é maior que zero. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:N', NULL, '[REGRA_OCORRENCIA_UNITARIA_I012]: Verifica se o registro ocorreu apenas uma vez por arquivo, no caso de o tipo da escrituração ser “A” ou “Z”. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.'),
(3, '03', 'NAT_LIVR', 'Natureza do livro auxiliar.', 'C', '020', NULL, NULL, 1, NULL, 3, '1:N', NULL, '[REGRA_OCORRENCIA_UNITARIA_I012]: Verifica se o registro ocorreu apenas uma vez por arquivo, no caso de o tipo da escrituração ser “A” ou “Z”. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.'),
(4, '04', 'TIPO', 'Tipo do livro auxiliar: A – Livro Diário Auxiliar, Z – Livro Razão Auxiliar.', 'C', '001', NULL, '[\"A\",\"Z\"]', 1, '[REGRA_VALIDA_TIPO_LIVRO_AUXILIAR]: Verifica, caso o campo indicador de existência de NIRE – IND_NIRE (Campo 13 do Registro 0000) – seja igual a 1 (possui registro na Junta Comercial), se o campo tipo de escrituração do livro associado – TIPO (Campo 04) – é igual a “0 – Digital (incluído no Sped)”, ou seja, se o livro principal for digital e a empresa possuir registro na Junta Comercial, seus livros auxiliares devem ser\r\ndigitais. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:N', NULL, '[REGRA_OCORRENCIA_UNITARIA_I012]: Verifica se o registro ocorreu apenas uma vez por arquivo, no caso de o tipo da escrituração ser “A” ou “Z”. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.'),
(5, '05', 'COD_HASH_AUX', 'Hash do livro auxiliar transmitido.', 'C', '040', NULL, NULL, 1, '[REGRA_CAMPO_ COD_HASH_AUX _OBRIGATORIO]: Verifica se o campo código Hash do arquivo correspondente ao livro auxiliar – COD_HASH_AUX (Campo 05) – foi preenchido quando o campo indicador\r\nda forma de escrituração contábil – IND_ESC (Campo 02 do registro I010) – for igual a “R” ou “B” e o campo\r\ntipo de escrituração do livro associado – TIPO (Campo 04) – for igual a “0”. Se a regra não for cumprida, o PGE\r\ndo Sped Contábil gera um erro.\r\n[REGRA_VALIDA_HEXADECIMAL]: Verifica se o campo código Hash do arquivo correspondente ao livro auxiliar – COD_HASH_AUX (Campo 05) – só contém algarismos (de 0 a 9) e os caracteres de A até F (em maiúsculas). Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.\r\n', 3, '1:N', NULL, '[REGRA_OCORRENCIA_UNITARIA_I012]: Verifica se o registro ocorreu apenas uma vez por arquivo, no caso de o tipo da escrituração ser “A” ou “Z”. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.');

