INSERT INTO `bloco_i015` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I015\".', 'C', '004', NULL, '\"I015\"', 1, NULL, 4, '0:N', NULL, '[REGRA_VALIDA_CONTA_RESUMIDA_AUXILIAR]: Verifica se o campo indicador da forma da\r\nescrituração contábil – IND_ESC (campo 02) do registro I010 – é igual a “R” ou “B” e se o campo código da conta analítica do livro diário com escrituração resumida – COD_CTA_RES (Campo 02) – possui uma correspondência idêntica ao campo código da conta analítica/grupo de contas – COD_CTA (campo 06) – do registro I050. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(2, '02', 'COD_CTA_RES', 'Código da conta sintética usada no livro principal que se refere à escrituração auxiliar.', 'C', '0', NULL, NULL, 1, '[REGRA_VALIDA_CONTA_RESUMIDA_AUXILIAR]: Verifica se o campo indicador da forma da\r\nescrituração contábil – IND_ESC (campo 02) do registro I010 – é igual a “R” ou “B” e se o campo código da conta analítica do livro diário com escrituração resumida – COD_CTA_RES (Campo 02) – possui uma\r\ncorrespondência idêntica ao campo código da conta analítica/grupo de contas – COD_CTA (campo 06) – do registro I050. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_CONTA_AUXILIAR_RESUMIDA]: Verifica se o IND_ESC (campo 02) do registro I010\r\nse o campo indicador da forma da escrituração contábil – IND_ESC (campo 02) do registro I010 – é igual a “A”\r\nou “Z” e se o campo código da conta analítica do livro diário com escrituração resumida – COD_CTA_RES\r\n(Campo 02) – possui uma correspondência idêntica ao campo código da conta analítica/grupo de contas – COD_CTA (campo 06) – do registro I050, para o campo indicador do tipo de conta – IND_CTA (campo 04) – do registro I050 igual a “S” (sintética). Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.', 4, '0:N', NULL, '[REGRA_VALIDA_CONTA_RESUMIDA_AUXILIAR]: Verifica se o campo indicador da forma da\r\nescrituração contábil – IND_ESC (campo 02) do registro I010 – é igual a “R” ou “B” e se o campo código da conta analítica do livro diário com escrituração resumida – COD_CTA_RES (Campo 02) – possui uma correspondência idêntica ao campo código da conta analítica/grupo de contas – COD_CTA (campo 06) – do registro I050. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');

