INSERT INTO `bloco_i020` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I020\".', 'C', '004', NULL, '\"I020\"', 1, NULL, 3, '0:N', NULL, '[REGRA_CAMPOS_ADICIONAIS]: Os campos adicionais acrescentados aos registros não serão validados. Entretanto deverá ser permitida a existência do campo adicional.'),
(2, '02', 'REG_CAMPO', 'Código do registro que recepciona o\r\ncampo adicional', 'C', '004', NULL, '[do “I050” ao “I355”]', 1, '[REGRA_REG_COD_NUM_AD_DUPLICADO]: Verifica se o registro não é duplicado considerando a chave código do registro que recepciona o campo adicional + número sequencial do campo adicional (REG_COD + NUM_AD). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '0:N', NULL, '[REGRA_CAMPOS_ADICIONAIS]: Os campos adicionais acrescentados aos registros não serão validados. Entretanto deverá ser permitida a existência do campo adicional.'),
(3, '03', 'NUM_AD', 'Número sequencial do campo adicional.', 'N', NULL, NULL, NULL, 1, NULL, 3, '0:N', NULL, '[REGRA_CAMPOS_ADICIONAIS]: Os campos adicionais acrescentados aos registros não serão validados. Entretanto deverá ser permitida a existência do campo adicional.'),
(4, '04', 'CAMPO', 'Nome do campo adicional.\r\n', 'C', NULL, NULL, NULL, 1, NULL, 3, '0:N', NULL, '[REGRA_CAMPOS_ADICIONAIS]: Os campos adicionais acrescentados aos registros não serão validados. Entretanto deverá ser permitida a existência do campo adicional.'),
(5, '05', 'DESCRICÃO ', 'Descrição do campo adicional.', 'C', NULL, NULL, NULL, 0, NULL, 3, '0:N', NULL, '[REGRA_CAMPOS_ADICIONAIS]: Os campos adicionais acrescentados aos registros não serão validados. Entretanto deverá ser permitida a existência do campo adicional.'),
(6, '06', 'TIPO', 'Indicação do tipo de dado (N:numérico; C:\r\ncaractere). N: numérico - campos adicionais que conterão informações de valores em espécie (moeda), com duas decimais. C: caractere - campos adicionais que conterão outras informações que não sejam valores em espécie (moeda), Exemplos: Códigos, CNPJ,\r\nCPF, etc.\r\nObservação: Os campos adicionais do tipo N (numérico) deverão ser preenchidos sem\r\nos separadores de milhar, sinais ou quaisquer outros caracteres\r\n(tais como: \".\"; \"-\" ou \"%\"),\r\ndevendo a vírgula ser utilizada como\r\nseparador decimal (Vírgula: caractere 44 da Tabela ASCII). \r\n', 'C', NULL, NULL, '[“N”,”C”]', 1, NULL, 3, '0:N', NULL, '[REGRA_CAMPOS_ADICIONAIS]: Os campos adicionais acrescentados aos registros não serão validados. Entretanto deverá ser permitida a existência do campo adicional.');

