INSERT INTO `bloco_i030` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(2, '02', 'DNRC_ABERT', 'Texto fixo contendo “TERMO DE ABERTURA”', 'C', '017', NULL, '“TERMO DE ABERTURA”\r\n', 1, NULL, 3, '1:1', NULL, '[REGRA_OCORRENCIA_UNITARIA_ARQ]: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I030” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(3, '03', 'NUM_ORD', 'Número de ordem do instrumento de escrituração', 'N', NULL, NULL, NULL, 1, '[REGRA_MAIOR_QUE_ZERO]:Verifica se o valor do campo número de ordem do instrumento de\r\nescrituração – NUM_ORD (Campo 02) – é maior que zero. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:1', NULL, 'REGRA_OCORRENCIA_UNITARIA_ARQ: Verifica se o registro ocorreu apenas uma vez por arquivo,\r\nconsiderando a chave “I030” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(4, '04', 'NAT_LIVR', 'Natureza do livro; finalidade a que se destina o instrumento.\r\n', 'C', '80', NULL, NULL, 1, '[REGRA_VALIDA_IDENT_MF_LIVRO_RAS]:Verifica, quando o campo identificador de moeda funcional– IDENT_MF (Campo 19) do registro 0000 for igual a “S”, se o campo NAT_LIVR (Campo 04) é igual a “RAZAO_AUXILIAR_DAS_SUBCONTAS_MF”; e verifica, quando o campo identificador de moeda funcional – IDENT_MF (Campo 19) do registro 0000 for igual a “N”, se o campo NAT_LIVR (Campo 04) é igual a “RAZAO_AUXILIAR_DAS_SUBCONTAS”. Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.\r\n\r\n[REGRA_VALIDA_CONTEUDO_NAT_LIVR]:Verifica se o campo natureza do livro – NAT_LIVR (Campo04) – é igual ao campo NAT_LIVRO (Campo 04) do registro J900. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro\r\n', 3, '1:1', NULL, 'REGRA_OCORRENCIA_UNITARIA_ARQ: Verifica se o registro ocorreu apenas uma vez por arquivo,\r\nconsiderando a chave “I030” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(5, '05', 'QTD_LIN', 'Quantidade total de linhas do arquivo digital.', 'N', NULL, NULL, NULL, 1, '[REGRA_IGUAL_QTD_LIN_REG9999]:Verifica se o valor do campo quantidade total de linhas do arquivo digital – QTD_LIN (Campo 05) – é igual ao valor do campo quantidade total de linhas do arquivo digital – QTD_LIN – do registro 9999. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n', 3, '1:1', NULL, 'REGRA_OCORRENCIA_UNITARIA_ARQ: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I030” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(6, '06', 'NOME', 'Nome empresarial', 'C', NULL, NULL, NULL, 1, '[REGRA_IGUAL_NOME_REG0000]:Verifica se o conteúdo do campo nome empresarial – NOME (Campo06) – é igual ao conteúdo do campo nome empresarial da pessoa jurídica – NOME (Campo 05) – do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n', 3, '1:1', NULL, 'REGRA_OCORRENCIA_UNITARIA_ARQ: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I030” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(7, '07', 'NIRE', 'Número de Identificação do Registro de\r\nEmpresas da Junta Comercial.', 'N', '011', NULL, NULL, 0, '[REGRA_VALIDA_NIRE]:Verifica se a regra de formação do código do campo número de identificação do registro de empresas da Junta Comercial – NIRE (Campo 07) – é válida. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_NIRE_UF]:Verifica se os dois primeiros dígitos do campo número de identificação do registro de empresas da Junta Comercial – NIRE (Campo 07) – correspondem à Unidade da Federação informada no campo Unidade da Federação – UF – do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_CAMPO_OBRIGATORIO_NIRE]:- Verifica, caso o campo indicador de existência de NIRE – IND_NIRE (Campo 13) – do registro 0000 seja igual a “0” (empresa não registro na Junta Comercial), se o campo número de identificação do registro de empresas da Junta Comercial – NIRE (Campo 07) – não foi preenchido. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n- Verifica, caso o campo indicador de existência de NIRE – IND_NIRE (Campo 13) – do registro 0000 seja igual a “1” (empresa possui registro na Junta Comercial), se o campo número de identificação do registro de empresas da Junta Comercial – NIRE (Campo 07) – foi preenchido. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:1', NULL, 'REGRA_OCORRENCIA_UNITARIA_ARQ: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I030” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(8, '08', 'CNPJ', 'Número de inscrição no CNPJ. ', 'N', '014', NULL, NULL, 1, ' [REGRA_IGUAL_CNPJ_REG0000]:Verifica se o conteúdo do CNPJ (Campo 08) é igual ao conteúdo do campo CNPJ (Campo 06) do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:1', NULL, 'REGRA_OCORRENCIA_UNITARIA_ARQ: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I030” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(9, '09', 'DT_ARQ', 'Data do arquivamento dos atos constitutivos.', 'N', '008', NULL, NULL, 0, '[REGRA_DATA_INI_MAIOR_ADV]:Verifica se o campo data de arquivamento do ato de conversão de sociedade simples em sociedade empresária – DT_ARQ_CONV (Campo 10) – foi preenchido com a data igual ou anterior à data do campo data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.', 3, '1:1', NULL, 'REGRA_OCORRENCIA_UNITARIA_ARQ: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I030” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(10, '10', ' DT_ARQ_CONV', 'Data de arquivamento do ato de conversão de sociedade simples em sociedade empresária.', 'N', '008', NULL, NULL, 0, '[REGRA_DATA_INI_MAIOR]:Verifica se o campo data de arquivamento do ato de conversão de sociedade simples em sociedade empresária – DT_ARQ_CONV (Campo 10) – foi preenchido com a data igual ou anterior à data do campo data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.\r\n\r\n[REGRA_PREENCHE_DATA_I030]: Verifica, caso o campo data de arquivamento dos atos constitutivos – “DT_ARQ” (Campo 09) – não esteja preenchido, se o campo DT_ARQ_CONV (Campo 10) data de\r\narquivamento do ato de conversão de sociedade simples em sociedade empresária – DT_ARQ_CONV (Campo 10) – foi preenchido. Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.', 3, '1:1', NULL, 'REGRA_OCORRENCIA_UNITARIA_ARQ: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I030” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(11, '11', 'DESC_MUN', 'Município', 'C', NULL, NULL, NULL, 0, NULL, 3, '1:1', NULL, 'REGRA_OCORRENCIA_UNITARIA_ARQ: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I030” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(12, '12', 'DT_EX_SOCIAL', 'Data de encerramento do exercício social.', 'N', '008', NULL, NULL, 1, '[REGRA_OBRIGATORIA_DT_EX_SOCIAL]: Verifica se o campo data de encerramento do exercício social – DT_EX_SOCIAL (Campo 12) – foi preenchido. Se a regra não for cumprida, o PGE do Sped Contábil gera\r\num erro.', 3, '1:1', NULL, 'REGRA_OCORRENCIA_UNITARIA_ARQ: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “I030” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');

