--
-- Estrutura para tabela `bloco_i050`
--

DROP TABLE IF EXISTS `bloco_i050`;
CREATE TABLE IF NOT EXISTS `bloco_i050` (
  `id` int NOT NULL AUTO_INCREMENT,
  `num` varchar(10) NOT NULL COMMENT 'Nº (ordem)',
  `campo` varchar(50) NOT NULL COMMENT 'Nome do campo (ex: REG)',
  `descricao` text NOT NULL COMMENT 'Descrição do campo',
  `tipo` char(1) NOT NULL COMMENT 'Tipo (C = caractere, N = numérico, etc.)',
  `tamanho` varchar(10) DEFAULT NULL COMMENT 'Tamanho do campo',
  `decimal` varchar(10) DEFAULT NULL COMMENT 'Casas decimais (se aplicável)',
  `valores_validos` varchar(255) DEFAULT NULL COMMENT 'Valores válidos',
  `obrigatorio` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = Sim, 0 = Não',
  `regras_validacao` text COMMENT 'Regras de validação do campo',
  `nivel_hierarquico` int DEFAULT NULL,
  `ocorrencia` varchar(10) DEFAULT NULL,
  `campos_chave` varchar(255) DEFAULT NULL,
  `regras_registro` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Despejando dados para a tabela `bloco_i050`
--

INSERT INTO `bloco_i050` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I050\".', 'C', '004', NULL, '\"I050\"', 1, NULL, 3, '1:N', NULL, '[REGRA_COD_CTA_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave “código da conta analítica/grupo de contas” (COD_CTA). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_AGL_CCUS_VAZIO_PREENCHIDO]: Verifica se existe, entre os registros filhos I052 do mesmo pai (registro I050), um registro I052 com COD_CCUS (Campo 02) vazio e outro registro I052 com COD_CCUS\r\n(Campo 02) preenchido, ambos com o mesmo código de aglutinação – COD_AGL (Campo 03) do registro I052. Caso essa situação ocorra, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_I051_OBRIGATORIO]: Verifica se o campo 0000.COD_PLAN_REF foi informado e não foi realizado o mapeamento das contas contábeis no plano referencial informado. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(2, '02', 'DT_ALT', 'Data da inclusão/alteração do plano de contas.', 'N', '008', NULL, NULL, 1, '[REGRA_ANO_ALT_MAIOR_ANO_FIN]: Verifica se o ano da data de inclusão/alteração – DT_ALT (Campo02) – é maior que o ano da data final das informações contidas no arquivo – DT_FIN (Campo 04) do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.\r\n', 3, '1:N', NULL, '[REGRA_COD_CTA_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave “código da conta analítica/grupo de contas” (COD_CTA). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_AGL_CCUS_VAZIO_PREENCHIDO]: Verifica se existe, entre os registros filhos I052 do mesmo pai (registro I050), um registro I052 com COD_CCUS (Campo 02) vazio e outro registro I052 com COD_CCUS\r\n(Campo 02) preenchido, ambos com o mesmo código de aglutinação – COD_AGL (Campo 03) do registro I052. Caso essa situação ocorra, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_I051_OBRIGATORIO]: Verifica se o campo 0000.COD_PLAN_REF foi informado e não foi realizado o mapeamento das contas contábeis no plano referencial informado. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(3, '03', 'COD_NAT', 'Código da natureza da conta/grupo de contas, conforme tabela publicada pelo Sped.', 'C', '002', NULL, NULL, 1, '[REGRA_TABELA_NATUREZA]:Verifica se o código informado no campo código da natureza da conta/grupo de contas – COD_NAT (Campo 03) – existe na Tabela de Naturezas das Contas/Grupo de Contas. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:N', NULL, '[REGRA_COD_CTA_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave “código da conta analítica/grupo de contas” (COD_CTA). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_AGL_CCUS_VAZIO_PREENCHIDO]: Verifica se existe, entre os registros filhos I052 do mesmo pai (registro I050), um registro I052 com COD_CCUS (Campo 02) vazio e outro registro I052 com COD_CCUS\r\n(Campo 02) preenchido, ambos com o mesmo código de aglutinação – COD_AGL (Campo 03) do registro I052. Caso essa situação ocorra, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_I051_OBRIGATORIO]: Verifica se o campo 0000.COD_PLAN_REF foi informado e não foi realizado o mapeamento das contas contábeis no plano referencial informado. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(4, '04', 'IND_CTA', 'Indicador do tipo de conta: A = Analítica; S = Sintética.', 'C', '001', NULL, '[\"A\",\"S\"]', 1, NULL, 3, '1:N', NULL, '[REGRA_COD_CTA_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave “código da conta analítica/grupo de contas” (COD_CTA). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_AGL_CCUS_VAZIO_PREENCHIDO]: Verifica se existe, entre os registros filhos I052 do mesmo pai (registro I050), um registro I052 com COD_CCUS (Campo 02) vazio e outro registro I052 com COD_CCUS\r\n(Campo 02) preenchido, ambos com o mesmo código de aglutinação – COD_AGL (Campo 03) do registro I052. Caso essa situação ocorra, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_I051_OBRIGATORIO]: Verifica se o campo 0000.COD_PLAN_REF foi informado e não foi realizado o mapeamento das contas contábeis no plano referencial informado. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(5, '05', 'NIVEL', 'Nível da conta analítica/grupo de contas.\r\n', 'N', NULL, NULL, NULL, 1, '[REGRA_MAIOR_QUE_UM]:Verifica se o valor informado no campo nível da conta/grupo de contas – NIVEL (Campo 05) – é maior ou igual a 1. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_NIVEL_CONTAS]:Verifica, caso o campo indicador da forma de escrituração contábil – IND_ESC (Campo 02) – do registro I010 seja igual a “G”, “R” ou “B”, o campo indicador do tipo de conta – IND_CTA (Campo 04) – seja igual a “A” (Analítica), e o campo código da natureza da conta/grupo de contas –\r\nCOD_NAT (Campo 03) – seja igual a “01” (ativo), “02” (passivo) ou “03” (patrimônio líquido), se o campo nível da conta analítica/grupo de contas – NIVEL (Campo 05) – é maior ou igual a “4”. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:N', NULL, '[REGRA_COD_CTA_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave “código da conta analítica/grupo de contas” (COD_CTA). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_AGL_CCUS_VAZIO_PREENCHIDO]: Verifica se existe, entre os registros filhos I052 do mesmo pai (registro I050), um registro I052 com COD_CCUS (Campo 02) vazio e outro registro I052 com COD_CCUS\r\n(Campo 02) preenchido, ambos com o mesmo código de aglutinação – COD_AGL (Campo 03) do registro I052. Caso essa situação ocorra, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_I051_OBRIGATORIO]: Verifica se o campo 0000.COD_PLAN_REF foi informado e não foi realizado o mapeamento das contas contábeis no plano referencial informado. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(6, '06', 'COD_CTA', 'Código da conta analítica/grupo de contas.', 'C', NULL, NULL, NULL, 1, '[REGRA_COD_CTA_IGUAL_COD_CTA_SUP]:Verifica de o código da conta analítica/grupo de contas – COD_CTA (Campo 06) – é diferente do código da conta sintética /grupo de contas de nível imediatamente superior – COD_CTA_SUP (Campo 07). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:N', NULL, '[REGRA_COD_CTA_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave “código da conta analítica/grupo de contas” (COD_CTA). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_AGL_CCUS_VAZIO_PREENCHIDO]: Verifica se existe, entre os registros filhos I052 do mesmo pai (registro I050), um registro I052 com COD_CCUS (Campo 02) vazio e outro registro I052 com COD_CCUS\r\n(Campo 02) preenchido, ambos com o mesmo código de aglutinação – COD_AGL (Campo 03) do registro I052. Caso essa situação ocorra, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_I051_OBRIGATORIO]: Verifica se o campo 0000.COD_PLAN_REF foi informado e não foi realizado o mapeamento das contas contábeis no plano referencial informado. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(7, '07', 'COD_CTA_SUP', 'Código da conta sintética /grupo de contas de nível imediatamente superior.\r\n', 'C', NULL, NULL, NULL, 0, '[REGRA_COD_CTA_SUP_OBRIGATORIO]: Verifica se o campo nível da conta analítica/grupo de contas – NIVEL (Campo 05) – é maior que 1. Se afirmativo executa a REGRA_CAMPO_OBRIGATORIO. Se a regra\r\nnão for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_CTA_DE_NIVEL_SUPERIOR_INVALIDA]:Verifica se o campo nível da conta analítica/grupo de contas – NIVEL (Campo 05) – é maior que 1. Caso seja maior que 1, verifica as seguintes regras: REGRA_CODIGO_CONTA_NIVEL_SUPERIOR_INVALIDO: Verifica se o campo código da conta sintética/grupo de contas de nível imediatamente superior – COD_CTA_SUP (Campo 07) – existe no plano de\r\ncontas (registro I050).\r\n\r\n\r\n[REGRA_CONTA_SUPERIOR_NAO_SE_APLICA]:Verifica, caso o campo nível da conta analítica/grupo de contas – NIVEL (Campo 05) – seja igual “1”, se o campo código da conta analítica/grupo de contas de nível imediatamente superior – COD_CTA_SUP (Campo 07) – não foi informado. Se a regra não for cumprida, o\r\nPGE do Sped Contábil gera um erro.\r\n\r\n', 3, '1:N', NULL, '[REGRA_COD_CTA_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave “código da conta analítica/grupo de contas” (COD_CTA). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_AGL_CCUS_VAZIO_PREENCHIDO]: Verifica se existe, entre os registros filhos I052 do mesmo pai (registro I050), um registro I052 com COD_CCUS (Campo 02) vazio e outro registro I052 com COD_CCUS\r\n(Campo 02) preenchido, ambos com o mesmo código de aglutinação – COD_AGL (Campo 03) do registro I052. Caso essa situação ocorra, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_I051_OBRIGATORIO]: Verifica se o campo 0000.COD_PLAN_REF foi informado e não foi realizado o mapeamento das contas contábeis no plano referencial informado. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(8, '08', 'CTA', 'Nome da conta analítica/grupo de contas.', 'C', NULL, NULL, NULL, 0, NULL, 3, '1:N', NULL, '[REGRA_COD_CTA_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave “código da conta analítica/grupo de contas” (COD_CTA). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_AGL_CCUS_VAZIO_PREENCHIDO]: Verifica se existe, entre os registros filhos I052 do mesmo pai (registro I050), um registro I052 com COD_CCUS (Campo 02) vazio e outro registro I052 com COD_CCUS\r\n(Campo 02) preenchido, ambos com o mesmo código de aglutinação – COD_AGL (Campo 03) do registro I052. Caso essa situação ocorra, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_I051_OBRIGATORIO]: Verifica se o campo 0000.COD_PLAN_REF foi informado e não foi realizado o mapeamento das contas contábeis no plano referencial informado. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');

