--
-- Estrutura para tabela `bloco_i051`
--

DROP TABLE IF EXISTS `bloco_i051`;
CREATE TABLE IF NOT EXISTS `bloco_i051` (
  `id` int NOT NULL AUTO_INCREMENT,
  `num` varchar(10) NOT NULL COMMENT 'Nº (ordem)',
  `campo` varchar(50) NOT NULL COMMENT 'Nome do campo (ex: REG)',
  `descricao` text NOT NULL COMMENT 'Descrição do campo',
  `tipo` char(1) NOT NULL COMMENT 'Tipo (C = caractere, N = numérico, etc.)',
  `tamanho` varchar(10) DEFAULT NULL COMMENT 'Tamanho do campo',
  `decimal` varchar(10) DEFAULT NULL COMMENT 'Casas decimais (se aplicável)',
  `valores_validos` varchar(255) DEFAULT NULL COMMENT 'Valores válidos',
  `obrigatorio` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = Sim, 0 = Não',
  `regras_validacao` text COMMENT 'Regras de validação do campo',
  `nivel_hierarquico` int DEFAULT NULL,
  `ocorrencia` varchar(10) DEFAULT NULL,
  `campos_chave` varchar(255) DEFAULT NULL,
  `regras_registro` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Despejando dados para a tabela `bloco_i051`
--

INSERT INTO `bloco_i051` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I051\".', 'C', '004', NULL, '\"I051\"', 1, NULL, 4, '0:N', NULL, '[REGRA_REGISTRO_PARA_CONTA_ANALITICA]: O registro I051 somente poderá existir quando o campo indicador do tipo de conta – IND_CTA (Campo 04) – do registro I050 for igual a “A”, ou seja, quando a\r\nconta informada no registro I050 for analítica. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_NATUREZA_CONTA_DIFERENTE]: Verifica, quando a natureza da conta (I050.COD_NAT) “pai” informada no registro I050 (I050.COD_CTA) é igual “01” (Ativo), “02” (Passivo) ou “03” (Patrimônio Líquido), se a natureza da conta “filha” mapeada no registro I051 (I051.COD_CTA_REF) é igual a “01”, “02”\r\nou “03”; e verifica, quando a natureza da conta (I050.COD_NAT) “pai” informada no registro I050 (I050.COD_CTA) é igual “04”(conta de resultado)), se a natureza da conta “filha” mapeada no registro I051\r\n(I051.COD_CTA_REF) é igual a “04)”, quando foi informado plano de contas referencial no registro 0000 (0000.COD_PLAN_REF). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(2, '02', 'COD_CCUS ', 'Código do centro de custo.', 'C', NULL, NULL, NULL, 1, '[REGRA_CCUS_NO_CENTRO_CUSTOS_N3]:Verifica se o código do centro de custo – COD_CCUS\r\n(Campo 02) – existe no registro I100 (Centro de Custos). Se a regra não for cumprida, o PGE do Sped Contábil\r\ngera um erro.', 4, '0:N', NULL, '[REGRA_REGISTRO_PARA_CONTA_ANALITICA]: O registro I051 somente poderá existir quando o campo indicador do tipo de conta – IND_CTA (Campo 04) – do registro I050 for igual a “A”, ou seja, quando a\r\nconta informada no registro I050 for analítica. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_NATUREZA_CONTA_DIFERENTE]: Verifica, quando a natureza da conta (I050.COD_NAT) “pai” informada no registro I050 (I050.COD_CTA) é igual “01” (Ativo), “02” (Passivo) ou “03” (Patrimônio Líquido), se a natureza da conta “filha” mapeada no registro I051 (I051.COD_CTA_REF) é igual a “01”, “02”\r\nou “03”; e verifica, quando a natureza da conta (I050.COD_NAT) “pai” informada no registro I050 (I050.COD_CTA) é igual “04”(conta de resultado)), se a natureza da conta “filha” mapeada no registro I051\r\n(I051.COD_CTA_REF) é igual a “04)”, quando foi informado plano de contas referencial no registro 0000 (0000.COD_PLAN_REF). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(3, '03', 'COD_CTA_REF', 'Código da conta de acordo com o plano de contas referencial, conforme tabela\r\npublicada pelos órgãos indicados no campo\r\nCOD_PLAN_REF do registro 0000.', 'C', NULL, NULL, NULL, 1, '[REGRA_VALIDADE_COD_CTA_PAD]:Verifica se o período de validade da conta no plano de contas referencial está dentro do período da escrituração (Campos data inicial das informações contidas no arquivo – DT_INI – e data final das informações contidas no arquivo – DT_FIN – do registro 0000). Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.\r\n\r\n[REGRA_NAO_EXISTE_COD_CTA_PAD]:Verifica se o campo código da conta de acordo com plano de contas referencial – COD_CTA_REF (Campo 04) – existe no plano de contas referencial. Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.\r\n', 4, '0:N', NULL, '[REGRA_REGISTRO_PARA_CONTA_ANALITICA]: O registro I051 somente poderá existir quando o campo indicador do tipo de conta – IND_CTA (Campo 04) – do registro I050 for igual a “A”, ou seja, quando a\r\nconta informada no registro I050 for analítica. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_NATUREZA_CONTA_DIFERENTE]: Verifica, quando a natureza da conta (I050.COD_NAT) “pai” informada no registro I050 (I050.COD_CTA) é igual “01” (Ativo), “02” (Passivo) ou “03” (Patrimônio Líquido), se a natureza da conta “filha” mapeada no registro I051 (I051.COD_CTA_REF) é igual a “01”, “02”\r\nou “03”; e verifica, quando a natureza da conta (I050.COD_NAT) “pai” informada no registro I050 (I050.COD_CTA) é igual “04”(conta de resultado)), se a natureza da conta “filha” mapeada no registro I051\r\n(I051.COD_CTA_REF) é igual a “04)”, quando foi informado plano de contas referencial no registro 0000 (0000.COD_PLAN_REF). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');

