--
-- Estrutura para tabela `bloco_i052`
--

DROP TABLE IF EXISTS `bloco_i052`;
CREATE TABLE IF NOT EXISTS `bloco_i052` (
  `id` int NOT NULL AUTO_INCREMENT,
  `num` varchar(10) NOT NULL COMMENT 'Nº (ordem do campo)',
  `campo` varchar(50) NOT NULL COMMENT 'Nome do campo',
  `descricao` text NOT NULL COMMENT 'Descrição oficial do manual',
  `tipo` char(1) NOT NULL COMMENT 'Tipo (C=caractere, N=numérico, D=data)',
  `tamanho` varchar(10) DEFAULT NULL COMMENT 'Tamanho do campo',
  `decimal` varchar(10) DEFAULT NULL COMMENT 'Casas decimais',
  `valores_validos` varchar(255) DEFAULT NULL COMMENT 'Valores válidos',
  `obrigatorio` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=Sim, 0=Não',
  `regras_validacao` text COMMENT 'Regras de validação',
  `nivel_hierarquico` int DEFAULT NULL,
  `ocorrencia` varchar(10) DEFAULT NULL,
  `campos_chave` varchar(255) DEFAULT NULL,
  `regras_registro` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Despejando dados para a tabela `bloco_i052`
--

INSERT INTO `bloco_i052` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I052\"', 'C', '004', NULL, '\"I052\"', 1, NULL, 4, '0:N', NULL, '[REGRA_REGISTRO_PARA_CONTA_ANALITICA]: O registro I052 somente poderá existir quando o campo indicador do tipo de conta – IND_CTA (Campo 04) – do registro I050 for igual a “A”, ou seja, quando a\r\nconta informada no registro I050 for analítica. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_COD_CCUS_COD_AGL_DUPLICIDADE]: Verifica se o registro não é duplicado considerando a chave código do centro de custo + código de aglutinação utilizado nas demonstrações contábeis (COD_CCUS +\r\nCOD_AGL). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_EXISTE_I052_CTA_SINTETICA]: Verifica se existe um registro I052 filho de um registro I050\r\ncom indicador do tipo de conta – IND_CTA (Campo 04) igual a “S” (Sintética). Se a situação ocorrer, o PGE do\r\nSped Contábil gera um erro.\r\n\r\n[REGRA_AGLUTINACAO_EM_SINTETICA]: Verifica se existe código de aglutinação – COD_AGL (Campo 03) – em alguma linha sintética dos registros J100 ou J150 (indicador do código de aglutinação –\r\nIND_COD_AGL – Campo 03 dos registros J100 e J150 – igual a “T” – Totalizador), cujo pai – registro J005 – satisfaça as seguintes condições: DT_INI (Campo 02) do registro J005 maior ou igual que DT_INI (Campo 03) do registro 0000; e DT_FIN (Campo 03) do registro J005 menor ou igual que DT_FIN (Campo 04) do registro\r\n0000. Se a situação ocorrer, o PGE do Sped Contábil gera um erro (não pode haver código aglutinação que foi\r\ncadastrado no registro I052 em linha sintética dos registros J100 e J150 – Os códigos de aglutinação informado\r\nnas linhas totalizadoras devem ser diferentes dos cadastrados no registro I052 para as contas analíticas).'),
(2, '02', 'COD_CCUS', 'Código do centro de custo. ', 'C', NULL, NULL, NULL, 0, '[REGRA_CCUS_NO_CENTRO_CUSTOS_N3]:Verifica se o código do centro de custos – COD_CCUS\r\n(Campo 02) – existe no registro I100 (Centro de Custos). Se a regra não for cumprida, o PGE do Sped Contábil\r\ngera um erro.', 4, '0:N', NULL, '[REGRA_REGISTRO_PARA_CONTA_ANALITICA]: O registro I052 somente poderá existir quando o campo indicador do tipo de conta – IND_CTA (Campo 04) – do registro I050 for igual a “A”, ou seja, quando a\r\nconta informada no registro I050 for analítica. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_COD_CCUS_COD_AGL_DUPLICIDADE]: Verifica se o registro não é duplicado considerando a chave código do centro de custo + código de aglutinação utilizado nas demonstrações contábeis (COD_CCUS +\r\nCOD_AGL). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_EXISTE_I052_CTA_SINTETICA]: Verifica se existe um registro I052 filho de um registro I050\r\ncom indicador do tipo de conta – IND_CTA (Campo 04) igual a “S” (Sintética). Se a situação ocorrer, o PGE do\r\nSped Contábil gera um erro.\r\n\r\n[REGRA_AGLUTINACAO_EM_SINTETICA]: Verifica se existe código de aglutinação – COD_AGL (Campo 03) – em alguma linha sintética dos registros J100 ou J150 (indicador do código de aglutinação –\r\nIND_COD_AGL – Campo 03 dos registros J100 e J150 – igual a “T” – Totalizador), cujo pai – registro J005 – satisfaça as seguintes condições: DT_INI (Campo 02) do registro J005 maior ou igual que DT_INI (Campo 03) do registro 0000; e DT_FIN (Campo 03) do registro J005 menor ou igual que DT_FIN (Campo 04) do registro\r\n0000. Se a situação ocorrer, o PGE do Sped Contábil gera um erro (não pode haver código aglutinação que foi\r\ncadastrado no registro I052 em linha sintética dos registros J100 e J150 – Os códigos de aglutinação informado\r\nnas linhas totalizadoras devem ser diferentes dos cadastrados no registro I052 para as contas analíticas).'),
(3, '03', 'COD_AGL', 'Código de aglutinação utilizado nas demonstrações contábeis do Bloco J.', 'C', NULL, NULL, NULL, 1, NULL, 4, '0:N', NULL, '[REGRA_REGISTRO_PARA_CONTA_ANALITICA]: O registro I052 somente poderá existir quando o campo indicador do tipo de conta – IND_CTA (Campo 04) – do registro I050 for igual a “A”, ou seja, quando a\r\nconta informada no registro I050 for analítica. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n\r\n[REGRA_COD_CCUS_COD_AGL_DUPLICIDADE]: Verifica se o registro não é duplicado considerando a chave código do centro de custo + código de aglutinação utilizado nas demonstrações contábeis (COD_CCUS +\r\nCOD_AGL). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_EXISTE_I052_CTA_SINTETICA]: Verifica se existe um registro I052 filho de um registro I050\r\ncom indicador do tipo de conta – IND_CTA (Campo 04) igual a “S” (Sintética). Se a situação ocorrer, o PGE do\r\nSped Contábil gera um erro.\r\n\r\n[REGRA_AGLUTINACAO_EM_SINTETICA]: Verifica se existe código de aglutinação – COD_AGL (Campo 03) – em alguma linha sintética dos registros J100 ou J150 (indicador do código de aglutinação –\r\nIND_COD_AGL – Campo 03 dos registros J100 e J150 – igual a “T” – Totalizador), cujo pai – registro J005 – satisfaça as seguintes condições: DT_INI (Campo 02) do registro J005 maior ou igual que DT_INI (Campo 03) do registro 0000; e DT_FIN (Campo 03) do registro J005 menor ou igual que DT_FIN (Campo 04) do registro\r\n0000. Se a situação ocorrer, o PGE do Sped Contábil gera um erro (não pode haver código aglutinação que foi\r\ncadastrado no registro I052 em linha sintética dos registros J100 e J150 – Os códigos de aglutinação informado\r\nnas linhas totalizadoras devem ser diferentes dos cadastrados no registro I052 para as contas analíticas).');

