DROP TABLE IF EXISTS `bloco_i053`;
CREATE TABLE IF NOT EXISTS `bloco_i053` (
  `id` int NOT NULL AUTO_INCREMENT,
  `num` varchar(10) NOT NULL COMMENT 'Nº (ordem do campo)',
  `campo` varchar(50) NOT NULL COMMENT 'Nome do campo',
  `descricao` text NOT NULL COMMENT 'Descrição oficial do manual',
  `tipo` char(1) NOT NULL COMMENT 'Tipo (C=caractere, N=numérico, D=data)',
  `tamanho` varchar(10) DEFAULT NULL COMMENT 'Tamanho do campo',
  `decimal` varchar(10) DEFAULT NULL COMMENT 'Casas decimais',
  `valores_validos` varchar(255) DEFAULT NULL COMMENT 'Valores válidos',
  `obrigatorio` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1=Sim, 0=Não',
  `regras_validacao` text COMMENT 'Regras de validação',
  `nivel_hierarquico` int DEFAULT NULL,
  `ocorrencia` varchar(10) DEFAULT NULL,
  `campos_chave` varchar(255) DEFAULT NULL,
  `regras_registro` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Despejando dados para a tabela `bloco_i053`
--

INSERT INTO `bloco_i053` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I053\".', 'C', '004', NULL, '\"I053\"', 1, NULL, 4, '0:N', NULL, '[REGRA_REGISTRO_PARA_CONTA_ANALITICA]: O registro somente poderá existir quando o valor do campo indicador do tipo de conta – IND_CTA (Campo 04) – do registro I050 for igual a “A” (Analítica). Se a\r\nregra não for cumprida, o sistema gera um erro.\r\n\r\n[REGRA_COD_CTA_DUPLICIDADE]: Verifica se o campo código da subconta correlata –\r\nCOD_CNT_CORR (Campo 03) – pertence a uma única conta no plano de contas (campo código da conta analítica/grupo de contas – COD_CTA – campo 06 do registro I050). Se a regra não for cumprida, o sistema\r\ngera um erro.\r\n\r\n[REGRA_SUB_CONTA_PAI]: Verifica se a subconta informada no campo código da subconta correlata – COD_CNT_CORR (Campo 03), quando aparece no registro I050 (campo código da conta analítica/grupo de\r\ncontas – COD_CTA – campo 06 do registro I050), não possui filhos I053. Se a regra não for cumprida, o sistema gera um erro.'),
(2, '02', 'COD_IDT', 'Código de identificação do grupo de conta-subconta(s).', 'C', '006', NULL, NULL, 1, '[REGRA_ COD_IDT_UNICO_POR_CONTA]:Verifica se todos os I053 filhos de uma conta do plano de contas (I050.COD_CTA) (campo código da conta analítica/grupo de contas – COD_CTA – campo 06 do registro I050) possuem o mesmo código de identificação do grupo de conta-subconta(s) – COD_IDT (Campo 02). O erro ocorre se os filhos de uma conta do plano de contas (I050) possuem códigos de identificação do grupo de conta-subconta(s) – COD_IDT (Campo 02) – diferentes entre si. Se a regra não for cumprida, o PGE do Sped Contábil\r\ngera um erro.\r\n', 4, '0:N', NULL, '[REGRA_REGISTRO_PARA_CONTA_ANALITICA]: O registro somente poderá existir quando o valor do campo indicador do tipo de conta – IND_CTA (Campo 04) – do registro I050 for igual a “A” (Analítica). Se a\r\nregra não for cumprida, o sistema gera um erro.\r\n\r\n[REGRA_COD_CTA_DUPLICIDADE]: Verifica se o campo código da subconta correlata –\r\nCOD_CNT_CORR (Campo 03) – pertence a uma única conta no plano de contas (campo código da conta analítica/grupo de contas – COD_CTA – campo 06 do registro I050). Se a regra não for cumprida, o sistema\r\ngera um erro.\r\n\r\n[REGRA_SUB_CONTA_PAI]: Verifica se a subconta informada no campo código da subconta correlata – COD_CNT_CORR (Campo 03), quando aparece no registro I050 (campo código da conta analítica/grupo de\r\ncontas – COD_CTA – campo 06 do registro I050), não possui filhos I053. Se a regra não for cumprida, o sistema gera um erro.'),
(3, '03', 'COD_CNT_CORR', 'Código da subconta correlata (deve estar no\r\nplano de contas e só pode estar relacionada a um único grupo).', 'C', NULL, NULL, NULL, 1, '[REGRA_SUBCONTA_NO_PLANO_CONTAS]:Verifica se a subconta informada no campo código da\r\nsubconta correlata – COD_CNT_CORR (Campo 03) existe no plano de contas (I050.COD_CTA). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 4, '0:N', NULL, '[REGRA_REGISTRO_PARA_CONTA_ANALITICA]: O registro somente poderá existir quando o valor do campo indicador do tipo de conta – IND_CTA (Campo 04) – do registro I050 for igual a “A” (Analítica). Se a\r\nregra não for cumprida, o sistema gera um erro.\r\n\r\n[REGRA_COD_CTA_DUPLICIDADE]: Verifica se o campo código da subconta correlata –\r\nCOD_CNT_CORR (Campo 03) – pertence a uma única conta no plano de contas (campo código da conta analítica/grupo de contas – COD_CTA – campo 06 do registro I050). Se a regra não for cumprida, o sistema\r\ngera um erro.\r\n\r\n[REGRA_SUB_CONTA_PAI]: Verifica se a subconta informada no campo código da subconta correlata – COD_CNT_CORR (Campo 03), quando aparece no registro I050 (campo código da conta analítica/grupo de\r\ncontas – COD_CTA – campo 06 do registro I050), não possui filhos I053. Se a regra não for cumprida, o sistema gera um erro.'),
(4, '04', 'NAT_SUB_CNT', 'Natureza da subconta correlata (conforme\r\ntabela de natureza da subconta publicada no\r\nSped).', 'C', '002', NULL, NULL, 1, '[REGRA_NAT_090_UNICA_POR_CONTA]:Verifica se existe, no máximo, duas subcontas de natureza 90 ou 91 ou 92 ou 93 (I053.NAT_SUB_CNT) para cada conta (campo código da conta analítica/grupo de contas –\r\nCOD_CTA – campo 06 do registro I050). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n', 4, '0:N', NULL, '[REGRA_REGISTRO_PARA_CONTA_ANALITICA]: O registro somente poderá existir quando o valor do campo indicador do tipo de conta – IND_CTA (Campo 04) – do registro I050 for igual a “A” (Analítica). Se a\r\nregra não for cumprida, o sistema gera um erro.\r\n\r\n[REGRA_COD_CTA_DUPLICIDADE]: Verifica se o campo código da subconta correlata –\r\nCOD_CNT_CORR (Campo 03) – pertence a uma única conta no plano de contas (campo código da conta analítica/grupo de contas – COD_CTA – campo 06 do registro I050). Se a regra não for cumprida, o sistema\r\ngera um erro.\r\n\r\n[REGRA_SUB_CONTA_PAI]: Verifica se a subconta informada no campo código da subconta correlata – COD_CNT_CORR (Campo 03), quando aparece no registro I050 (campo código da conta analítica/grupo de\r\ncontas – COD_CTA – campo 06 do registro I050), não possui filhos I053. Se a regra não for cumprida, o sistema gera um erro.');

