INSERT INTO `bloco_i100` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I100\".', 'C', '004', NULL, '\"I100\"', 1, NULL, 3, '0:N', NULL, '[REGRA_COD_CCUS_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave código do centro de custos (COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n'),
(2, '02', 'DT_ALT', 'Data da inclusão/alteração.', 'N', '008', NULL, NULL, 1, '[REGRAS_DT_ALT_DATA_MAIOR]:Verifica se a data da inclusão/alteração – DT_ALT (Campo 02) – é menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '0:N', NULL, '[REGRA_COD_CCUS_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave código do centro de custos (COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(3, '03', 'COD_CCUS', 'Código do centro de custos.', 'C', NULL, NULL, NULL, 1, NULL, 3, '0:N', NULL, '[REGRA_COD_CCUS_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave código do centro de custos (COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(4, '04', 'CCUS', 'Nome do centro de custos.', 'C', NULL, NULL, NULL, 1, NULL, 3, '0:N', NULL, '[REGRA_COD_CCUS_ DUPLICADO]: Verifica se o registro não é duplicado considerando a chave código do centro de custos (COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');

