) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Despejando dados para a tabela `bloco_i150`
--

INSERT INTO `bloco_i150` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I150\".', 'C', '004', NULL, '\"I150\"', 1, NULL, 3, '0:N', NULL, '[REGRA_CONTINUIDADE_SALDOS_PERIODICOS]: Verifica, se existir pelo menos um registro I150, se há registro I155 para todos os meses informados no intervalo do arquivo informado no registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_DATA_MES]: Verifica se a data de início do período – DT_INI (Campo 02) – e a data de fim do período – DT_FIN (Campo 03) – estão contidas no mesmo mês. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.\r\n\r\n[REGRA_DUPLICIDADE_PERIODO_SALDO_PERIODICO]: Verificar se chave data de início do período + data de fim do período (DT_INI + DT_FIN) aparece mais de uma vez no registro ou se existe mais de um\r\nregistro para o mesmo mês. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_MES_I157]: Verifica, caso exista registro I157, se o mês do campo data de início do período – DT_INI (Campo 02) – é igual ao mês do campo data inicial das informações contidas no arquivo – DT_INI (Campo 03) do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(2, '02', 'DT_INI', 'Data de início do período.', 'N', '008', NULL, NULL, 1, '[REGRAS] [REGRAS_DATA_INTERVALO_DO_ARQUIVO]:Verifica se a data de início do período – DT_INI (Campo 02) – é maior ou igual que a data inicial das informações contidas no arquivo – DT_INI (Campo 03) – do registro 0000 e é menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) – do\r\nregistro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRAS_DT_INI_MAIOR_DT_FIN]:Verifica se a data de início do período – DT_INI (Campo 02) – é menor ou igual à data de fim do período – “DT_FIN” (Campo 03). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRAS_DT_INI_INICIO_MES]: Verifica, caso a data de início do período – DT_INI (Campo 02) – seja diferente da data inicial das informações contidas no arquivo – DT_INI (Campo 03) do registro 0000, se a data inicial – DT_INI (Campo 02) – corresponde ao primeiro dia do mês. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '0:N', NULL, '[REGRA_CONTINUIDADE_SALDOS_PERIODICOS]: Verifica, se existir pelo menos um registro I150, se há registro I155 para todos os meses informados no intervalo do arquivo informado no registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_DATA_MES]: Verifica se a data de início do período – DT_INI (Campo 02) – e a data de fim do período – DT_FIN (Campo 03) – estão contidas no mesmo mês. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.\r\n\r\n[REGRA_DUPLICIDADE_PERIODO_SALDO_PERIODICO]: Verificar se chave data de início do período + data de fim do período (DT_INI + DT_FIN) aparece mais de uma vez no registro ou se existe mais de um\r\nregistro para o mesmo mês. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_MES_I157]: Verifica, caso exista registro I157, se o mês do campo data de início do período – DT_INI (Campo 02) – é igual ao mês do campo data inicial das informações contidas no arquivo – DT_INI (Campo 03) do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(3, '03', 'DT_FIN', 'Data de fim do período.', 'N', '008', NULL, NULL, 1, '[REGRAS] [REGRAS_DATA_INTERVALO_DO_ARQUIVO]: Verifica se a data de início do período – DT_INI (Campo 02) – é maior ou igual que a data inicial das informações contidas no arquivo – DT_INI (Campo 03) – do registro\r\n0000 e é menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n\r\n[REGRAS_DT_FIN_FIM_MES]: Verifica, caso a data de fim do período – DT_FIN (Campo 03) – seja diferente da data final das informações contidas no arquivo – DT_FIN (Campo 04) do registro 0000, se a data fim – DT_FIM (Campo 03) – corresponde ao último dia do mês. Se a regra não for cumprida, o PGE do Sped Contábil\r\ngera um erro.', 3, '0:N', NULL, '[REGRA_CONTINUIDADE_SALDOS_PERIODICOS]: Verifica, se existir pelo menos um registro I150, se há registro I155 para todos os meses informados no intervalo do arquivo informado no registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_DATA_MES]: Verifica se a data de início do período – DT_INI (Campo 02) – e a data de fim do período – DT_FIN (Campo 03) – estão contidas no mesmo mês. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.\r\n\r\n[REGRA_DUPLICIDADE_PERIODO_SALDO_PERIODICO]: Verificar se chave data de início do período + data de fim do período (DT_INI + DT_FIN) aparece mais de uma vez no registro ou se existe mais de um\r\nregistro para o mesmo mês. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_MES_I157]: Verifica, caso exista registro I157, se o mês do campo data de início do período – DT_INI (Campo 02) – é igual ao mês do campo data inicial das informações contidas no arquivo – DT_INI (Campo 03) do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');

