--
-- Estrutura para tabela `bloco_i250`
--

DROP TABLE IF EXISTS `bloco_i250`;
CREATE TABLE IF NOT EXISTS `bloco_i250` (
  `id` int NOT NULL AUTO_INCREMENT,
  `num` varchar(10) NOT NULL COMMENT 'Nº (ordem do campo)',
  `campo` varchar(50) NOT NULL COMMENT 'Nome do campo',
  `descricao` text NOT NULL COMMENT 'Descrição do campo conforme manual da ECD 2024',
  `tipo` char(1) NOT NULL COMMENT 'Tipo do campo (C=Caractere, N=Numérico)',
  `tamanho` varchar(10) DEFAULT NULL COMMENT 'Tamanho do campo',
  `decimal` varchar(10) DEFAULT NULL COMMENT 'Casas decimais (quando aplicável)',
  `valores_validos` varchar(255) DEFAULT NULL COMMENT 'Valores válidos (quando aplicável)',
  `obrigatorio` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=Sim, 0=Não',
  `regras_validacao` text COMMENT 'Regras de validação conforme o manual da ECD',
  `nivel_hierarquico` int DEFAULT NULL,
  `ocorrencia` varchar(10) DEFAULT NULL,
  `campos_chave` varchar(255) DEFAULT NULL,
  `regras_registro` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Despejando dados para a tabela `bloco_i250`
--

INSERT INTO `bloco_i250` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I250\".', 'C', '004', NULL, '\"I250\"', 1, NULL, 4, '0:N', NULL, '[REGRA_HISTORICO_OBRIGATORIO]: Verifica se o histórico completo da partida ou histórico complementar – HIST (Campo 08) ou o código do histórico padronizado – COD_HIST_PAD (Campo 07) – estão preenchidos (um dos dois campos deve estar preenchido). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDACAO_VALOR_DEB]: Verifica se a soma dos débitos (por período informado no registro I150 e conta) de lançamentos é igual ao valor da partida – VL_DC (Campo 04) –, com o indicador da natureza da partida – IND_DC (Campo 05) – igual a “D” (Débito), no período, no caso de escriturações do tipo G (Livro Diário Completo, sem escrituração auxiliar) ou R (Livro Diário com Escrituração Resumida, com escrituração\r\nauxiliar). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_VALIDACAO_VALOR_CRED]: Verifica se a soma dos créditos (por período informado no Registro I150 e conta) de lançamentos é igual ao valor da partida – VL_DC (Campo 04) –, com o indicador da natureza da partida – IND_DC (Campo 05) – igual a “C” (Crédito), no período, no caso de escriturações do tipo G (Livro\r\nDiário Completo, sem escrituração auxiliar) ou R (Livro Diário com Escrituração Resumida, com escrituração\r\nauxiliar). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\nREGRA_VALIDA_CAMPOS_MF_I250: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim): [REGRA_VALIDACAO_VALOR_DEB]: Verifica se a soma dos débitos (por período informado no registro I150 e conta) de lançamentos é igual ao valor da partida em moeda funcional, convertido em reais – VL_DC_MF (Campo 10) –, com indicador da partida em moeda funcional – IND_DC_MF (Campo 11) – igual a “D” (Débito), no período, no caso de escriturações do tipo G (Livro Diário Completo, sem escrituração auxiliar), R (Livro Diário com Escrituração Resumida, com escrituração auxiliar) ou A (Livro Diário Auxiliar ao Diário com Escrituração Resumida). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDACAO_VALOR_CRED]: Verifica se a soma dos créditos (por período informado no registro I150 e conta) de lançamentos é igual ao valor da partida em moeda funcional, convertido em reais – VL_DC_MF (Campo 10) –, com indicador da partida em moeda funcional – IND_DC_MF (Campo 11) – igual a “C” (Crédito), no período, no caso de escriturações do tipo G (Livro Diário\r\nCompleto, sem escrituração auxiliar), R (Livro Diário com Escrituração Resumida, com escrituração auxiliar) ou A (Livro Diário Auxiliar ao Diário com Escrituração Resumida). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPO_ADICIONAL_NUMERICO_MF]: Os campos adicionais de valores\r\ninseridos no registro I250 deverão ser preenchidos sem os separadores de milhar, sinais ou quaisquer outros caracteres (tais como “.” “-“ “%”), podendo a vírgula ser utilizada como separador decimal (Vírgula: caractere 44 da Tabela ASCII). Deverão ter tamanho máximo 19, com 2 casas decimais.'),
(2, '02', 'COD_CTA', 'Código da conta analítica debitada/creditada.', 'C', NULL, NULL, NULL, 1, '[REGRA_CONTA_PARA_LANCAMENTO]: Verifica se a “REGRA_CONTA_ANALITICA” e a “REGRA_CONTA_NO_PLANO_CONTAS” foram atendidas. Se as regras não forem cumpridas, o PGE do Sped Contábil gera um erro.\r\n[REGRA_LANC_EXT_CONTA_RESULTADO]: Verifica, quando o campo indicador do tipo de lançamento – IND_LCTO (Campo 05) – do registro I200 for igual a “X” (Lançamento extemporâneo), se o código da conta informado no registro I250 – COD_CTA (Campo 02) – é igual ao código da conta informado no registro I050 – COD_CTA (Campo 06) – e sua natureza – COD_NAT (Campo 03) do registro I050 – é diferente de “4” (Conta de resultado). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 4, '0:N', NULL, '[REGRA_HISTORICO_OBRIGATORIO]: Verifica se o histórico completo da partida ou histórico complementar – HIST (Campo 08) ou o código do histórico padronizado – COD_HIST_PAD (Campo 07) – estão preenchidos (um dos dois campos deve estar preenchido). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDACAO_VALOR_DEB]: Verifica se a soma dos débitos (por período informado no registro I150 e conta) de lançamentos é igual ao valor da partida – VL_DC (Campo 04) –, com o indicador da natureza da partida – IND_DC (Campo 05) – igual a “D” (Débito), no período, no caso de escriturações do tipo G (Livro Diário Completo, sem escrituração auxiliar) ou R (Livro Diário com Escrituração Resumida, com escrituração\nauxiliar). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDACAO_VALOR_CRED]: Verifica se a soma dos créditos (por período informado no Registro I150 e conta) de lançamentos é igual ao valor da partida – VL_DC (Campo 04) –, com o indicador da natureza da partida – IND_DC (Campo 05) – igual a “C” (Crédito), no período, no caso de escriturações do tipo G (Livro\nDiário Completo, sem escrituração auxiliar) ou R (Livro Diário com Escrituração Resumida, com escrituração\nauxiliar). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\nREGRA_VALIDA_CAMPOS_MF_I250: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim): [REGRA_VALIDACAO_VALOR_DEB]: Verifica se a soma dos débitos (por período informado no registro I150 e conta) de lançamentos é igual ao valor da partida em moeda funcional, convertido em reais – VL_DC_MF (Campo 10) –, com indicador da partida em moeda funcional – IND_DC_MF (Campo 11) – igual a “D” (Débito), no período, no caso de escriturações do tipo G (Livro Diário Completo, sem escrituração auxiliar), R (Livro Diário com Escrituração Resumida, com escrituração auxiliar) ou A (Livro Diário Auxiliar ao Diário com Escrituração Resumida). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDACAO_VALOR_CRED]: Verifica se a soma dos créditos (por período informado no registro I150 e conta) de lançamentos é igual ao valor da partida em moeda funcional, convertido em reais – VL_DC_MF (Campo 10) –, com indicador da partida em moeda funcional – IND_DC_MF (Campo 11) – igual a “C” (Crédito), no período, no caso de escriturações do tipo G (Livro Diário\nCompleto, sem escrituração auxiliar), R (Livro Diário com Escrituração Resumida, com escrituração auxiliar) ou A (Livro Diário Auxiliar ao Diário com Escrituração Resumida). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPO_ADICIONAL_NUMERICO_MF]: Os campos adicionais de valores\ninseridos no registro I250 deverão ser preenchidos sem os separadores de milhar, sinais ou quaisquer outros caracteres (tais como “.” “-“ “%”), podendo a vírgula ser utilizada como separador decimal (Vírgula: caractere 44 da Tabela ASCII). Deverão ter tamanho máximo 19, com 2 casas decimais.'),
(3, '03', 'COD_CCUS', 'Código do centro de custos.', 'C', NULL, NULL, NULL, 0, '[REGRA_CCUS_NO_CENTRO_CUSTOS]: Verifica se o código do centro de custos COD_CCUS (Campo 03) existe no registro I100 (Centro de Custos). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n', 4, '0:N', NULL, '[REGRA_HISTORICO_OBRIGATORIO]: Verifica se o histórico completo da partida ou histórico complementar – HIST (Campo 08) ou o código do histórico padronizado – COD_HIST_PAD (Campo 07) – estão preenchidos (um dos dois campos deve estar preenchido). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDACAO_VALOR_DEB]: Verifica se a soma dos débitos (por período informado no registro I150 e conta) de lançamentos é igual ao valor da partida – VL_DC (Campo 04) –, com o indicador da natureza da partida – IND_DC (Campo 05) – igual a “D” (Débito), no período, no caso de escriturações do tipo G (Livro Diário Completo, sem escrituração auxiliar) ou R (Livro Diário com Escrituração Resumida, com escrituração\nauxiliar). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDACAO_VALOR_CRED]: Verifica se a soma dos créditos (por período informado no Registro I150 e conta) de lançamentos é igual ao valor da partida – VL_DC (Campo 04) –, com o indicador da natureza da partida – IND_DC (Campo 05) – igual a “C” (Crédito), no período, no caso de escriturações do tipo G (Livro\nDiário Completo, sem escrituração auxiliar) ou R (Livro Diário com Escrituração Resumida, com escrituração\nauxiliar). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\nREGRA_VALIDA_CAMPOS_MF_I250: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim): [REGRA_VALIDACAO_VALOR_DEB]: Verifica se a soma dos débitos (por período informado no registro I150 e conta) de lançamentos é igual ao valor da partida em moeda funcional, convertido em reais – VL_DC_MF (Campo 10) –, com indicador da partida em moeda funcional – IND_DC_MF (Campo 11) – igual a “D” (Débito), no período, no caso de escriturações do tipo G (Livro Diário Completo, sem escrituração auxiliar), R (Livro Diário com Escrituração Resumida, com escrituração auxiliar) ou A (Livro Diário Auxiliar ao Diário com Escrituração Resumida). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDACAO_VALOR_CRED]: Verifica se a soma dos créditos (por período informado no registro I150 e conta) de lançamentos é igual ao valor da partida em moeda funcional, convertido em reais – VL_DC_MF (Campo 10) –, com indicador da partida em moeda funcional – IND_DC_MF (Campo 11) – igual a “C” (Crédito), no período, no caso de escriturações do tipo G (Livro Diário\nCompleto, sem escrituração auxiliar), R (Livro Diário com Escrituração Resumida, com escrituração auxiliar) ou A (Livro Diário Auxiliar ao Diário com Escrituração Resumida). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPO_ADICIONAL_NUMERICO_MF]: Os campos adicionais de valores\ninseridos no registro I250 deverão ser preenchidos sem os separadores de milhar, sinais ou quaisquer outros caracteres (tais como “.” “-“ “%”), podendo a vírgula ser utilizada como separador decimal (Vírgula: caractere 44 da Tabela ASCII). Deverão ter tamanho máximo 19, com 2 casas decimais.'),
