INSERT INTO `bloco_i300` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I300\".', 'C', '004', NULL, '\"I300\"', 1, NULL, 3, '0:N\n', '[DT_BCTE]', '[REGRA_DATA_BALANCETE_DUPLICADO]: Verifica se o registro não é duplicado considerando a chave data do balancete – “DT_BCTE” (Campo 02). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.'),
(2, '02', 'DT_BCTE', 'Data do balancete diário.', 'N', '008', NULL, NULL, 1, '[REGRAS_DATA_INTERVALO_DO_ARQUIVO]: Verifica se a data do balancete – DT_BCTE (Campo 02) – é maior ou igual que a data inicial das informações contidas no arquivo – DT_INI (Campo 03) – do registro 0000 e é menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '0:N\n', '[DT_BCTE]', '[REGRA_DATA_BALANCETE_DUPLICADO]: Verifica se o registro não é duplicado considerando a chave data do balancete – “DT_BCTE” (Campo 02). Se a regra não for cumprida, o PGE do Sped Contábil gera um\nerro.');

