--

INSERT INTO `bloco_i310` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I310\".', 'C', '004', NULL, '\"I310\"', 1, NULL, 4, '0:N', '[COD_CTA]+[COD_CCUS]', '[REGRA_DETALHE_BALANCETE_DUPLICADO]: Verifica se, para cada data do balancete – DT_BCTE (Campo 02) – do registro I300, o registro I310 não é duplicado considerando a chave código da conta analítica + código do centro de custos (COD_CTA + COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_VALIDACAO_DC_BALANCETE]: Verifica se a soma do total dos débitos do dia – VAL_DEBD (Campo 04) – de todas as contas contábeis/centro de custo é igual a soma do total dos créditos do dia – VAL_CREDD (Campo 05) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPOS_MF_I310]: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim):\r\n[REGRA_VALIDACAO_DC_BALANCETE_MF]: Verifica se o total dos débitos do dia em moeda funcional, convertido para reais – VAL_DEBD_MF (Campo 06) – de todas as contas contábeis/centro de custo é igual ao total dos créditos do dia em moeda funcional, convertido para reais – VAL_CREDD_MF (Campo 07) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_VALIDA_CAMPO_ADICIONAL_NUMERICO_MF]: Os campos adicionais de valores\r\ninseridos no registro I310 deverão ser preenchidos sem os separadores de milhar, sinais ou quaisquer outros caracteres (tais como “.” “-“ “%”), podendo a vírgula ser utilizada como separador decimal (Vírgula: caractere 44 da Tabela ASCII). Deverão ter tamanho máximo 19, com 2 casas decimais.'),
(2, '02', 'COD_CTA', 'Código da conta analítica debitada/creditada.', 'C', NULL, NULL, NULL, 1, '[REGRA_CONTA_PARA_LANCAMENTO]: Verifica se a “REGRA_CONTA_ANALITICA” e a “REGRA_CONTA_NO_PLANO_CONTAS” foram atendidas. Se as regras não forem cumpridas, o PGE do\r\nSped Contábil gera um erro.\r\n', 4, '0:N', '[COD_CTA]+[COD_CCUS]', '[REGRA_DETALHE_BALANCETE_DUPLICADO]: Verifica se, para cada data do balancete – DT_BCTE (Campo 02) – do registro I300, o registro I310 não é duplicado considerando a chave código da conta analítica + código do centro de custos (COD_CTA + COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDACAO_DC_BALANCETE]: Verifica se a soma do total dos débitos do dia – VAL_DEBD (Campo 04) – de todas as contas contábeis/centro de custo é igual a soma do total dos créditos do dia – VAL_CREDD (Campo 05) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPOS_MF_I310]: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim):\n[REGRA_VALIDACAO_DC_BALANCETE_MF]: Verifica se o total dos débitos do dia em moeda funcional, convertido para reais – VAL_DEBD_MF (Campo 06) – de todas as contas contábeis/centro de custo é igual ao total dos créditos do dia em moeda funcional, convertido para reais – VAL_CREDD_MF (Campo 07) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDA_CAMPO_ADICIONAL_NUMERICO_MF]: Os campos adicionais de valores\ninseridos no registro I310 deverão ser preenchidos sem os separadores de milhar, sinais ou quaisquer outros caracteres (tais como “.” “-“ “%”), podendo a vírgula ser utilizada como separador decimal (Vírgula: caractere 44 da Tabela ASCII). Deverão ter tamanho máximo 19, com 2 casas decimais.'),
(3, '03', 'COD_CCUS', 'Código do centro de custos.', 'C', NULL, NULL, NULL, 0, '[REGRA_CCUS_NO_CENTRO_CUSTOS]: Verifica se o código do centro de custos COD_CCUS (Campo 03) existe no registro I100 (Centro de Custos). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 4, '0:N', '[COD_CTA]+[COD_CCUS]', '[REGRA_DETALHE_BALANCETE_DUPLICADO]: Verifica se, para cada data do balancete – DT_BCTE (Campo 02) – do registro I300, o registro I310 não é duplicado considerando a chave código da conta analítica + código do centro de custos (COD_CTA + COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDACAO_DC_BALANCETE]: Verifica se a soma do total dos débitos do dia – VAL_DEBD (Campo 04) – de todas as contas contábeis/centro de custo é igual a soma do total dos créditos do dia – VAL_CREDD (Campo 05) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPOS_MF_I310]: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim):\n[REGRA_VALIDACAO_DC_BALANCETE_MF]: Verifica se o total dos débitos do dia em moeda funcional, convertido para reais – VAL_DEBD_MF (Campo 06) – de todas as contas contábeis/centro de custo é igual ao total dos créditos do dia em moeda funcional, convertido para reais – VAL_CREDD_MF (Campo 07) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDA_CAMPO_ADICIONAL_NUMERICO_MF]: Os campos adicionais de valores\ninseridos no registro I310 deverão ser preenchidos sem os separadores de milhar, sinais ou quaisquer outros caracteres (tais como “.” “-“ “%”), podendo a vírgula ser utilizada como separador decimal (Vírgula: caractere 44 da Tabela ASCII). Deverão ter tamanho máximo 19, com 2 casas decimais.'),
(4, '04', 'VAL_DEBD', 'Total dos débitos do dia.', 'N', '019', '02', NULL, 1, NULL, 4, '0:N', '[COD_CTA]+[COD_CCUS]', '[REGRA_DETALHE_BALANCETE_DUPLICADO]: Verifica se, para cada data do balancete – DT_BCTE (Campo 02) – do registro I300, o registro I310 não é duplicado considerando a chave código da conta analítica + código do centro de custos (COD_CTA + COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDACAO_DC_BALANCETE]: Verifica se a soma do total dos débitos do dia – VAL_DEBD (Campo 04) – de todas as contas contábeis/centro de custo é igual a soma do total dos créditos do dia – VAL_CREDD (Campo 05) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPOS_MF_I310]: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim):\n[REGRA_VALIDACAO_DC_BALANCETE_MF]: Verifica se o total dos débitos do dia em moeda funcional, convertido para reais – VAL_DEBD_MF (Campo 06) – de todas as contas contábeis/centro de custo é igual ao total dos créditos do dia em moeda funcional, convertido para reais – VAL_CREDD_MF (Campo 07) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDA_CAMPO_ADICIONAL_NUMERICO_MF]: Os campos adicionais de valores\ninseridos no registro I310 deverão ser preenchidos sem os separadores de milhar, sinais ou quaisquer outros caracteres (tais como “.” “-“ “%”), podendo a vírgula ser utilizada como separador decimal (Vírgula: caractere 44 da Tabela ASCII). Deverão ter tamanho máximo 19, com 2 casas decimais.'),
(5, '05', 'VAL_CRED', 'Total dos créditos do dia.', 'N', '019', '02', NULL, 1, NULL, 4, '0:N', '[COD_CTA]+[COD_CCUS]', '[REGRA_DETALHE_BALANCETE_DUPLICADO]: Verifica se, para cada data do balancete – DT_BCTE (Campo 02) – do registro I300, o registro I310 não é duplicado considerando a chave código da conta analítica + código do centro de custos (COD_CTA + COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDACAO_DC_BALANCETE]: Verifica se a soma do total dos débitos do dia – VAL_DEBD (Campo 04) – de todas as contas contábeis/centro de custo é igual a soma do total dos créditos do dia – VAL_CREDD (Campo 05) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPOS_MF_I310]: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim):\n[REGRA_VALIDACAO_DC_BALANCETE_MF]: Verifica se o total dos débitos do dia em moeda funcional, convertido para reais – VAL_DEBD_MF (Campo 06) – de todas as contas contábeis/centro de custo é igual ao total dos créditos do dia em moeda funcional, convertido para reais – VAL_CREDD_MF (Campo 07) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDA_CAMPO_ADICIONAL_NUMERICO_MF]: Os campos adicionais de valores\ninseridos no registro I310 deverão ser preenchidos sem os separadores de milhar, sinais ou quaisquer outros caracteres (tais como “.” “-“ “%”), podendo a vírgula ser utilizada como separador decimal (Vírgula: caractere 44 da Tabela ASCII). Deverão ter tamanho máximo 19, com 2 casas decimais.'),
(6, '06', 'VAL_DEB_MF', 'Total dos débitos do dia em moeda funcional, convertido para reais.', 'N', '019', '02', NULL, 0, NULL, 4, '0:N', '[COD_CTA]+[COD_CCUS]', '[REGRA_DETALHE_BALANCETE_DUPLICADO]: Verifica se, para cada data do balancete – DT_BCTE (Campo 02) – do registro I300, o registro I310 não é duplicado considerando a chave código da conta analítica + código do centro de custos (COD_CTA + COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDACAO_DC_BALANCETE]: Verifica se a soma do total dos débitos do dia – VAL_DEBD (Campo 04) – de todas as contas contábeis/centro de custo é igual a soma do total dos créditos do dia – VAL_CREDD (Campo 05) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPOS_MF_I310]: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim):\n[REGRA_VALIDACAO_DC_BALANCETE_MF]: Verifica se o total dos débitos do dia em moeda funcional, convertido para reais – VAL_DEBD_MF (Campo 06) – de todas as contas contábeis/centro de custo é igual ao total dos créditos do dia em moeda funcional, convertido para reais – VAL_CREDD_MF (Campo 07) – de todas as contas contábeis/centro de custos na mesma data do balancete – DT_BCTE (Campo 02) – do registro I300. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDA_CAMPO_ADICIONAL_NUMERICO_MF]: Os campos adicionais de valores\ninseridos no registro I310 deverão ser preenchidos sem os separadores de milhar, sinais ou quaisquer outros caracteres (tais como “.” “-“ “%”), podendo a vírgula ser utilizada como separador decimal (Vírgula: caractere 44 da Tabela ASCII). Deverão ter tamanho máximo 19, com 2 casas decimais.'),
