--
-- Estrutura para tabela `bloco_i350`
--

DROP TABLE IF EXISTS `bloco_i350`;
CREATE TABLE IF NOT EXISTS `bloco_i350` (
  `id` int NOT NULL AUTO_INCREMENT,
  `num` varchar(10) NOT NULL COMMENT 'Nº (ordem do campo)',
  `campo` varchar(50) NOT NULL COMMENT 'Nome do campo',
  `descricao` text NOT NULL COMMENT 'Descrição oficial do manual',
  `tipo` char(1) NOT NULL COMMENT 'Tipo (C=caractere, N=numérico, D=data)',
  `tamanho` varchar(10) DEFAULT NULL COMMENT 'Tamanho do campo',
  `decimal` varchar(10) DEFAULT NULL COMMENT 'Casas decimais',
  `valores_validos` varchar(255) DEFAULT NULL COMMENT 'Valores válidos (quando houver)',
  `obrigatorio` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=Sim, 0=Não (conforme manual)',
  `regras_validacao` varchar(1000) DEFAULT NULL COMMENT 'Regras de validação referenciadas no manual',
  `nivel_hierarquico` int DEFAULT NULL,
  `ocorrencia` varchar(10) DEFAULT NULL,
  `campos_chave` varchar(255) DEFAULT NULL,
  `regras_registro` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Despejando dados para a tabela `bloco_i350`
--

INSERT INTO `bloco_i350` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I350\".', 'C', '004', NULL, '\"I350\"', 1, NULL, 3, '0:N\n', ' [DT_RES]\n', '[REGRA_DT_RES_DUPLICIDADE]: Verifica se o registro não é duplicado considerando a chave data da apuração do resultado – DT_RES (Campo 02). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro. [REGRA_ENCERRAMENTO_EXERCICIO]: Verifica, quando a data do encerramento do exercício social – DT_EX_SOCIAL (Campo 12) do registro I030 – for maior ou igual que a data inicial das informações contidas no arquivo – DT_INI (Campo 03) do registro 0000 - e menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) do registro 0000 - e quando o indicador da forma da escrituração contábil – IND_ESC (Campo 02) do registro I010 - foi igual a “G”, “R” ou “B”, se existe pelo menos um registro I350 – Saldo das Contas de Resultado Antes do Encerramento – Identificação da Data – com a data da apuração do resultado – DT_RES (Campo 02) – igual à data do encerramento do exercício social – DT_EX_SOCIAL (Campo 12).'),
(2, '02', 'DT_RES', 'Data do saldo das contas de resultado antes do encerramento.', 'N', '008', NULL, NULL, 1, '[REGRAS_DATA_INTERVALO_DO_ARQUIVO]: Verifica se a data da apuração do resultado – DT_RES (Campo 02) – é maior ou igual à data inicial das informações contidas no arquivo – DT_INI (Campo 03) – do registro 0000 e é menor ou igual à data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '0:N\n', ' [DT_RES]', '[REGRA_DT_RES_DUPLICIDADE]: Verifica se o registro não é duplicado considerando a chave data da apuração do resultado – DT_RES (Campo 02). Se a regra não for cumprida, o PGE do Sped Contábil gera um\nerro. [REGRA_ENCERRAMENTO_EXERCICIO]: Verifica, quando a data do encerramento do exercício social – DT_EX_SOCIAL (Campo 12) do registro I030 – for maior ou igual que a data inicial das informações contidas no arquivo – DT_INI (Campo 03) do registro 0000 - e menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) do registro 0000 - e quando o indicador da forma da escrituração contábil – IND_ESC (Campo 02) do registro I010 - foi igual a “G”, “R” ou “B”, se existe pelo menos um registro I350 – Saldo das Contas de Resultado Antes do Encerramento – Identificação da Data – com a data da apuração do resultado – DT_RES (Campo 02) – igual à data do encerramento do exercício social – DT_EX_SOCIAL (Campo 12).');

