--
-- Estrutura para tabela `bloco_i355`
--

DROP TABLE IF EXISTS `bloco_i355`;
CREATE TABLE IF NOT EXISTS `bloco_i355` (
  `id` int NOT NULL AUTO_INCREMENT,
  `num` varchar(10) NOT NULL COMMENT 'Nº (ordem do campo)',
  `campo` varchar(50) NOT NULL COMMENT 'Nome do campo',
  `descricao` text NOT NULL COMMENT 'Descrição conforme Manual da ECD 2024',
  `tipo` char(1) NOT NULL COMMENT 'Tipo do campo (C=Caractere, N=Numérico)',
  `tamanho` varchar(10) DEFAULT NULL COMMENT 'Tamanho máximo do campo',
  `decimal` varchar(10) DEFAULT NULL COMMENT 'Número de casas decimais (quando aplicável)',
  `valores_validos` varchar(255) DEFAULT NULL COMMENT 'Valores válidos (quando aplicável)',
  `obrigatorio` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1=Sim, 0=Não (conforme manual)',
  `regras_validacao` text COMMENT 'Regras de validação conforme Manual da ECD 2024',
  `nivel_hierarquico` int DEFAULT NULL,
  `ocorrencia` varchar(10) DEFAULT NULL,
  `campos_chave` varchar(255) DEFAULT NULL,
  `regras_registro` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Despejando dados para a tabela `bloco_i355`
--

INSERT INTO `bloco_i355` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I355\".', 'C', '004', NULL, '\"I355\"', 1, NULL, 4, '0:N\n', '[COD_CTA]+[COD_CCUS]', '[REGRA_COD_CTA_DT_RES_DUPLICIDADE]: Verificar se, para uma mesma data de apuração do resultado – DT_RES (Campo 02) – do registro I350, o registro I355 não é duplicado considerando a chave código da conta analítica de resultado + código do centro de custos (COD_CTA + COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_REGISTRO_OBRIGATORIO_I350]: Verifica se existe lançamento de encerramento do tipo “E” (nas escriturações G e R) no campo indicador do tipo de lançamento – IND_LCTO (Campo 05) – do registro I200. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_VALIDACAO_CONTA_RESULTADO]: Verifica se, na data de encerramento, a soma do saldo final de cada conta de resultado – VL_SLD_FIN (Campo 08) – do registro I155 é igual a 0. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPOS_MF_I355]: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim): [REGRA_VALIDACAO_CONTA_RESULTADO_MF]: Verifica se, na data de encerramento, a\r\nsoma do saldo final de cada conta de resultado em moeda funcional, convertido para reais – VL_SLD_FIN_MF (Campo 14) – do registro I155 é igual a 0. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDACAO_SALDO_CONTA_MF]: Verifica se a soma de todos os lançamentos do tipo encerramento de conta de resultado – IND_LCTO (Campo 05) – do registro I200, para cada data – DT_RES (Campo 02) – do registro I350 e conta (considerando se é crédito ou débito), é igual ao valor do saldo final antes do lançamento de encerramento – VL_CTA_MF (Campo 06) – do registro I355 para escriturações do tipo G ou R (com o indicador de débito ou crédito invertido). Se a regra não for\r\ncumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPO_ADICIONAL_NUMERICO_MF]: Os campos adicionais de valores\r\ninseridos no registro I355 deverão ser preenchidos sem os separadores de milhar, sinais ou quaisquer outros caracteres (tais como “.” “-“ “%”), podendo a vírgula ser utilizada como separador decimal (Vírgula: caractere 44 da Tabela ASCII). Deverão ter tamanho máximo 19, com 2 casas decimais. [REGRA_VALIDACAO_SALDO_CONTA]: Verifica se a soma de todos os lançamentos do tipo encerramento de conta de resultado – IND_LCTO (Campo 05) – do registro I200, para cada data – DT_RES (Campo 02) – do registro I350 e conta (considerando se é crédito ou débito), é igual ao valor do saldo final antes do lançamento\r\nde encerramento – VL_CTA (Campo 04) – do registro I355 para escriturações do tipo G ou R (com o indicador de débito ou crédito invertido). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(2, '02', 'COD_CTA', 'Código da conta analítica de resultado.', 'C', NULL, NULL, NULL, 1, '[REGRA_CONTA_RESULTADO]: Verifica se o código da conta analítica de resultado – COD_NAT (Campo 03) – do registro I050 é de conta de resultado (código da natureza da conta/grupo de contas – COD_NAT – igual a “04” – Contas de Resultado). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_CONTA_PARA_LANCAMENTO]: Verifica se a “REGRA_CONTA_ANALITICA” e a\r\n“REGRA_CONTA_NO_PLANO_CONTAS” foram atendidas. Se as regras não forem cumpridas, o PGE do Sped Contábil gera um erro.\r\n', 4, '0:N\n', '[COD_CTA]+[COD_CCUS]', '[REGRA_COD_CTA_DT_RES_DUPLICIDADE]: Verificar se, para uma mesma data de apuração do resultado – DT_RES (Campo 02) – do registro I350, o registro I355 não é duplicado considerando a chave código da conta analítica de resultado + código do centro de custos (COD_CTA + COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_REGISTRO_OBRIGATORIO_I350]: Verifica se existe lançamento de encerramento do tipo “E” (nas escriturações G e R) no campo indicador do tipo de lançamento – IND_LCTO (Campo 05) – do registro I200. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDACAO_CONTA_RESULTADO]: Verifica se, na data de encerramento, a soma do saldo final de cada conta de resultado – VL_SLD_FIN (Campo 08) – do registro I155 é igual a 0. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPOS_MF_I355]: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim): [REGRA_VALIDACAO_CONTA_RESULTADO_MF]: Verifica se, na data de encerramento, a\nsoma do saldo final de cada conta de resultado em moeda funcional, convertido para reais – VL_SLD_FIN_MF (Campo 14) – do registro I155 é igual a 0. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDACAO_SALDO_CONTA_MF]: Verifica se a soma de todos os lançamentos do tipo encerramento de conta de resultado – IND_LCTO (Campo 05) – do registro I200, para cada data – DT_RES (Campo 02) – do registro I350 e conta (considerando se é crédito ou débito), é igual ao valor do saldo final antes do lançamento de encerramento – VL_CTA_MF (Campo 06) – do registro I355 para escriturações do tipo G ou R (com o indicador de débito ou crédito invertido). Se a regra não for\ncumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPO_ADICIONAL_NUMERICO_MF]: Os campos adicionais de valores\ninseridos no registro I355 deverão ser preenchidos sem os separadores de milhar, sinais ou quaisquer outros caracteres (tais como “.” “-“ “%”), podendo a vírgula ser utilizada como separador decimal (Vírgula: caractere 44 da Tabela ASCII). Deverão ter tamanho máximo 19, com 2 casas decimais. [REGRA_VALIDACAO_SALDO_CONTA]: Verifica se a soma de todos os lançamentos do tipo encerramento de conta de resultado – IND_LCTO (Campo 05) – do registro I200, para cada data – DT_RES (Campo 02) – do registro I350 e conta (considerando se é crédito ou débito), é igual ao valor do saldo final antes do lançamento\nde encerramento – VL_CTA (Campo 04) – do registro I355 para escriturações do tipo G ou R (com o indicador de débito ou crédito invertido). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(3, '03', 'COD_CCUS', 'Código do centro de custos.', 'C', NULL, NULL, NULL, 0, '[REGRA_CCUS_NO_CENTRO_CUSTOS]: Verifica se o código do centro de custos – COD_CCUS (Campo 03) – existe no registro I100 (Centro de Custos). Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.\r\n', 4, '0:N\n', '[COD_CTA]+[COD_CCUS]', '[REGRA_COD_CTA_DT_RES_DUPLICIDADE]: Verificar se, para uma mesma data de apuração do resultado – DT_RES (Campo 02) – do registro I350, o registro I355 não é duplicado considerando a chave código da conta analítica de resultado + código do centro de custos (COD_CTA + COD_CCUS). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_REGISTRO_OBRIGATORIO_I350]: Verifica se existe lançamento de encerramento do tipo “E” (nas escriturações G e R) no campo indicador do tipo de lançamento – IND_LCTO (Campo 05) – do registro I200. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\n[REGRA_VALIDACAO_CONTA_RESULTADO]: Verifica se, na data de encerramento, a soma do saldo final de cada conta de resultado – VL_SLD_FIN (Campo 08) – do registro I155 é igual a 0. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDA_CAMPOS_MF_I355]: Aciona as regras de validação dos campos adicionais quando o campo identificação de moeda funcional – IDENT_MF (Campo 19) – do registro 0000 estiver preenchido com “S” (Sim): [REGRA_VALIDACAO_CONTA_RESULTADO_MF]: Verifica se, na data de encerramento, a\nsoma do saldo final de cada conta de resultado em moeda funcional, convertido para reais – VL_SLD_FIN_MF (Campo 14) – do registro I155 é igual a 0. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro. [REGRA_VALIDACAO_SALDO_CONTA_MF]: Verifica se a soma de todos os lançamentos do tipo encerramento de conta de resultado – IND_LCTO (Campo 05) – do registro I200, para cada data – DT_RES (Campo 02) – do registro I350 e conta (considerando se é crédito ou débito), é igual ao valor do saldo final antes do lançamen