INSERT INTO `bloco_i510` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"I510\".', 'C', '004', NULL, '\"I510\"', 1, NULL, 3, '0:N\n', NULL, '[REGRA_COLUNAS_PAGINA]: O somatório dos campos largura da coluna no relatório – COL_CAMPO (Campo 07) – do registro I510 + número de registros I510 que aparecem no arquivo – 1 deverá ser igual ao\r\nnúmero máximo de caracteres que cabem em uma linha do livro que será impresso/visualizado. Considerar que\r\no livro será impresso/visualizado em papel A-4, com a orientação paisagem, margens de 1,5 cm e com fonte\r\nCourier. [REGRA_VALIDA_CONTEUDO_I510_LIVRO_RAS]: Verifica se a natureza do livro do registro I030 – NAT_LIVR (Campo 04) – o identifica como um livro “RAZAO_AUXILIAR_DAS_SUBCONTAS” ou “RAZAO_AUXILIAR_DAS_SUBCONTAS_MF” e aplica a validação da estrutura desse livro.\r\n'),
(2, '02', 'NM_CAMPO', 'Nome do campo, sem espaços em branco ou caractere especial.', 'C', '016', NULL, NULL, 1, NULL, 3, '0:N\n', NULL, '[REGRA_COLUNAS_PAGINA]: O somatório dos campos largura da coluna no relatório – COL_CAMPO (Campo 07) – do registro I510 + número de registros I510 que aparecem no arquivo – 1 deverá ser igual ao\nnúmero máximo de caracteres que cabem em uma linha do livro que será impresso/visualizado. Considerar que\no livro será impresso/visualizado em papel A-4, com a orientação paisagem, margens de 1,5 cm e com fonte\nCourier. [REGRA_VALIDA_CONTEUDO_I510_LIVRO_RAS]: Verifica se a natureza do livro do registro I030 – NAT_LIVR (Campo 04) – o identifica como um livro “RAZAO_AUXILIAR_DAS_SUBCONTAS” ou “RAZAO_AUXILIAR_DAS_SUBCONTAS_MF” e aplica a validação da estrutura desse livro.'),
