INSERT INTO `bloco_j005` (`num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal_place`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `regras_registro`, `campos_chave`) VALUES
('01', 'REG', 'Texto fixo contendo \"J005\".', 'C', '004', NULL, '\"J005\"', 1, NULL, 2, '0:N', '[REGRA_OBRIGATORIA_DEMONSTRACAO]: Verifica, se os registros J100 – Balanço Patrimonial – e J150 – Demonstração do Resultado do Exercício – foram preenchidos. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_REGISTRO_OBRIGATORIO_J005_FIM_EXERCICIO]: Quando a data de encerramento do exercício social – DT-EX-SOCIAL (Campo 12) – do registro I030 for maior ou igual que a data de inicial das informações contidas no arquivo – DT_INI (Campo 03) – do registro 0000 e menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000 e o indicador da forma de escrituração contábil – IND_ESC (Campo 02) – do registro I010 for igual a “G”, “R” ou “B”, deverão existir, no mínimo, um registro J005, cuja data final das demonstrações contábeis – DT_FIN (Campo 03) – seja igual a data de\r\nencerramento do exercício social – DT-EX-SOCIAL (Campo 12) – do registro I030, um registro J100 (Balanço Patrimonial) e um registro J150 (Demonstração do Resultado do Exercício). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_PERIODO_SUP_UM_ANO]: Verifica se o período entre a data inicial das demonstrações contábeis – DT_INI (Campo 02) – e a data final das demonstrações contábeis – DT_FIN (Campo 03) – é superior a um ano. Se a situação ocorrer, o PGE do Sped Contábil gera um aviso.\r\n\r\n[REGRA_ENC_OBRIGATORIO]: Se a identificação das demonstrações – ID_DEM (Campo 04) – for igual a “1” (Demonstrações contábeis do empresário ou sociedade empresária a que se refere a escrituração), se a data inicial das demonstrações contábeis – DT_INI (Campo 02) – for maior ou igual que a data inicial das informações\r\ncontidas no arquivo – DT_INI (Campo 03) do registro 0000 – e for menor ou igual que a data final das\r\ndemonstrações contábeis – DT_FIN (Campo 03), que também deve ser menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) do registro 0000, e se o registro J005 possui registros filhos J100 e J210, deve existir um registro I350 com data de apuração do resultado – DT_RES (Campo 02) – igual à data final das demonstrações contábeis – DT_FIN (Campo 03). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '[DT_INI+DT_FIN+ID_DEM]'),
('02', 'DT_INI', 'Data inicial das demonstrações contábeis.', 'N', '008', NULL, NULL, 1, '[REGRA_DATA_INI_MAIOR]: Verifica se a data inicial das demonstrações contábeis – DT_INI (Campo 02) – foi preenchida com a data igual ou anterior à data final da escrituração – DT_FIN (Campo 04 do regi', 2, '0:N', '[REGRA_OBRIGATORIA_DEMONSTRACAO]: Verifica, se os registros J100 – Balanço Patrimonial – e J150 – Demonstração do Resultado do Exercício – foram preenchidos. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_REGISTRO_OBRIGATORIO_J005_FIM_EXERCICIO]: Quando a data de encerramento do exercício social – DT-EX-SOCIAL (Campo 12) – do registro I030 for maior ou igual que a data de inicial das informações contidas no arquivo – DT_INI (Campo 03) – do registro 0000 e menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000 e o indicador da forma de escrituração contábil – IND_ESC (Campo 02) – do registro I010 for igual a “G”, “R” ou “B”, deverão existir, no mínimo, um registro J005, cuja data final das demonstrações contábeis – DT_FIN (Campo 03) – seja igual a data de\r\nencerramento do exercício social – DT-EX-SOCIAL (Campo 12) – do registro I030, um registro J100 (Balanço Patrimonial) e um registro J150 (Demonstração do Resultado do Exercício). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_PERIODO_SUP_UM_ANO]: Verifica se o período entre a data inicial das demonstrações contábeis – DT_INI (Campo 02) – e a data final das demonstrações contábeis – DT_FIN (Campo 03) – é superior a um ano. Se a situação ocorrer, o PGE do Sped Contábil gera um aviso.\r\n\r\n[REGRA_ENC_OBRIGATORIO]: Se a identificação das demonstrações – ID_DEM (Campo 04) – for igual a “1” (Demonstrações contábeis do empresário ou sociedade empresária a que se refere a escrituração), se a data inicial das demonstrações contábeis – DT_INI (Campo 02) – for maior ou igual que a data inicial das informações\r\ncontidas no arquivo – DT_INI (Campo 03) do registro 0000 – e for menor ou igual que a data final das\r\ndemonstrações contábeis – DT_FIN (Campo 03), que também deve ser menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) do registro 0000, e se o registro J005 possui registros filhos J100 e J210, deve existir um registro I350 com data de apuração do resultado – DT_RES (Campo 02) – igual à data final das demonstrações contábeis – DT_FIN (Campo 03). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '[DT_INI+DT_FIN+ID_DEM]'),
('03', 'DT_FIN', 'Data final das demonstrações contábeis.', 'N', '008', NULL, NULL, 1, '[REGRA_DATA_INI_MAIOR]: Verifica se a data inicial das demonstrações contábeis – DT_INI (Campo 02) – foi preenchida com a data igual ou anterior à data final da escrituração – DT_FIN (Campo 04 do regi', 2, '0:N', '[REGRA_OBRIGATORIA_DEMONSTRACAO]: Verifica, se os registros J100 – Balanço Patrimonial – e J150 – Demonstração do Resultado do Exercício – foram preenchidos. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_REGISTRO_OBRIGATORIO_J005_FIM_EXERCICIO]: Quando a data de encerramento do exercício social – DT-EX-SOCIAL (Campo 12) – do registro I030 for maior ou igual que a data de inicial das informações contidas no arquivo – DT_INI (Campo 03) – do registro 0000 e menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000 e o indicador da forma de escrituração contábil – IND_ESC (Campo 02) – do registro I010 for igual a “G”, “R” ou “B”, deverão existir, no mínimo, um registro J005, cuja data final das demonstrações contábeis – DT_FIN (Campo 03) – seja igual a data de\r\nencerramento do exercício social – DT-EX-SOCIAL (Campo 12) – do registro I030, um registro J100 (Balanço Patrimonial) e um registro J150 (Demonstração do Resultado do Exercício). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_PERIODO_SUP_UM_ANO]: Verifica se o período entre a data inicial das demonstrações contábeis – DT_INI (Campo 02) – e a data final das demonstrações contábeis – DT_FIN (Campo 03) – é superior a um ano. Se a situação ocorrer, o PGE do Sped Contábil gera um aviso.\r\n\r\n[REGRA_ENC_OBRIGATORIO]: Se a identificação das demonstrações – ID_DEM (Campo 04) – for igual a “1” (Demonstrações contábeis do empresário ou sociedade empresária a que se refere a escrituração), se a data inicial das demonstrações contábeis – DT_INI (Campo 02) – for maior ou igual que a data inicial das informações\r\ncontidas no arquivo – DT_INI (Campo 03) do registro 0000 – e for menor ou igual que a data final das\r\ndemonstrações contábeis – DT_FIN (Campo 03), que também deve ser menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) do registro 0000, e se o registro J005 possui registros filhos J100 e J210, deve existir um registro I350 com data de apuração do resultado – DT_RES (Campo 02) – igual à data final das demonstrações contábeis – DT_FIN (Campo 03). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '[DT_INI+DT_FIN+ID_DEM]'),
('04', 'ID_DEM', 'Identificação das demonstrações: 1 – demonstrações da pessoa jurídica a que se refere a escrituração; 2 – demonstrações consolidadas ou de outras pessoas jurídicas.', 'N', '001', NULL, '[1,2]', 1, '', 2, '0:N', '[REGRA_OBRIGATORIA_DEMONSTRACAO]: Verifica, se os registros J100 – Balanço Patrimonial – e J150 – Demonstração do Resultado do Exercício – foram preenchidos. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_REGISTRO_OBRIGATORIO_J005_FIM_EXERCICIO]: Quando a data de encerramento do exercício social – DT-EX-SOCIAL (Campo 12) – do registro I030 for maior ou igual que a data de inicial das informações contidas no arquivo – DT_INI (Campo 03) – do registro 0000 e menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000 e o indicador da forma de escrituração contábil – IND_ESC (Campo 02) – do registro I010 for igual a “G”, “R” ou “B”, deverão existir, no mínimo, um registro J005, cuja data final das demonstrações contábeis – DT_FIN (Campo 03) – seja igual a data de\r\nencerramento do exercício social – DT-EX-SOCIAL (Campo 12) – do registro I030, um registro J100 (Balanço Patrimonial) e um registro J150 (Demonstração do Resultado do Exercício). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_PERIODO_SUP_UM_ANO]: Verifica se o período entre a data inicial das demonstrações contábeis – DT_INI (Campo 02) – e a data final das demonstrações contábeis – DT_FIN (Campo 03) – é superior a um ano. Se a situação ocorrer, o PGE do Sped Contábil gera um aviso.\r\n\r\n[REGRA_ENC_OBRIGATORIO]: Se a identificação das demonstrações – ID_DEM (Campo 04) – for igual a “1” (Demonstrações contábeis do empresário ou sociedade empresária a que se refere a escrituração), se a data inicial das demonstrações contábeis – DT_INI (Campo 02) – for maior ou igual que a data inicial das informações\r\ncontidas no arquivo – DT_INI (Campo 03) do registro 0000 – e for menor ou igual que a data final das\r\ndemonstrações contábeis – DT_FIN (Campo 03), que também deve ser menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) do registro 0000, e se o registro J005 possui registros filhos J100 e J210, deve existir um registro I350 com data de apuração do resultado – DT_RES (Campo 02) – igual à data final das demonstrações contábeis – DT_FIN (Campo 03). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '[DT_INI+DT_FIN+ID_DEM]'),
('05', 'CAB_DEM', 'Cabeçalho das demonstrações. Preencher somente quando ID_DEM = 2 (Demonstrações consolidadas ou de outras pessoas jurídicas).', 'C', '65535', NULL, NULL, 0, '[REGRA_CAB_DEM_OBRIGATORIO]: Campo obrigatório quando a identificação das demonstrações –\r\nID_DEM (Campo 04) – for igual a “2” (Demonstrações consolidadas ou de outras pessoas jurídicas). Se a regra n', 2, '0:N', '[REGRA_OBRIGATORIA_DEMONSTRACAO]: Verifica, se os registros J100 – Balanço Patrimonial – e J150 – Demonstração do Resultado do Exercício – foram preenchidos. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_REGISTRO_OBRIGATORIO_J005_FIM_EXERCICIO]: Quando a data de encerramento do exercício social – DT-EX-SOCIAL (Campo 12) – do registro I030 for maior ou igual que a data de inicial das informações contidas no arquivo – DT_INI (Campo 03) – do registro 0000 e menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000 e o indicador da forma de escrituração contábil – IND_ESC (Campo 02) – do registro I010 for igual a “G”, “R” ou “B”, deverão existir, no mínimo, um registro J005, cuja data final das demonstrações contábeis – DT_FIN (Campo 03) – seja igual a data de\r\nencerramento do exercício social – DT-EX-SOCIAL (Campo 12) – do registro I030, um registro J100 (Balanço Patrimonial) e um registro J150 (Demonstração do Resultado do Exercício). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_PERIODO_SUP_UM_ANO]: Verifica se o período entre a data inicial das demonstrações contábeis – DT_INI (Campo 02) – e a data final das demonstrações contábeis – DT_FIN (Campo 03) – é superior a um ano. Se a situação ocorrer, o PGE do Sped Contábil gera um aviso.\r\n\r\n[REGRA_ENC_OBRIGATORIO]: Se a identificação das demonstrações – ID_DEM (Campo 04) – for igual a “1” (Demonstrações contábeis do empresário ou sociedade empresária a que se refere a escrituração), se a data inicial das demonstrações contábeis – DT_INI (Campo 02) – for maior ou igual que a data inicial das informações\r\ncontidas no arquivo – DT_INI (Campo 03) do registro 0000 – e for menor ou igual que a data final das\r\ndemonstrações contábeis – DT_FIN (Campo 03), que também deve ser menor ou igual que a data final das informações contidas no arquivo – DT_FIN (Campo 04) do registro 0000, e se o registro J005 possui registros filhos J100 e J210, deve existir um registro I350 com data de apuração do resultado – DT_RES (Campo 02) – igual à data final das demonstrações contábeis – DT_FIN (Campo 03). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', '[DT_INI+DT_FIN+ID_DEM]');

