--
-- Estrutura para tabela `bloco_j150`
--

DROP TABLE IF EXISTS `bloco_j150`;
CREATE TABLE IF NOT EXISTS `bloco_j150` (
  `num` char(2) NOT NULL,
  `campo` varchar(40) NOT NULL,
  `descricao` text NOT NULL,
  `tipo` char(1) NOT NULL,
  `tamanho` varchar(6) DEFAULT NULL,
  `decimal` smallint DEFAULT NULL,
  `valores_validos` varchar(200) DEFAULT NULL,
  `obrigatorio` tinyint(1) NOT NULL DEFAULT '1',
  `regras_validacao` varchar(200) DEFAULT NULL,
  `nivel_hierarquico` tinyint DEFAULT NULL,
  `ocorrencia` varchar(10) DEFAULT NULL,
  `campos_chave` varchar(255) DEFAULT NULL,
  `regras_registro` text,
  PRIMARY KEY (`num`,`campo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

--
-- Despejando dados para a tabela `bloco_j150`
--

INSERT INTO `bloco_j150` (`num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
('01', 'REG', 'Texto fixo contendo \"J150\".', 'C', '004', NULL, '\"J150\"', 1, NULL, 3, '0:N', '[COD_AGL] (para [IND_VL] = P ou N)', '[REGRA_SOMA_NIVEIS_DRE]: Verifica, para cada registro J150 com indicador do tipo de código de\r\naglutinação – IND_COD_AGL (Campo 04) - igual a “T” (totalizador), se o valor total do código de aglutinação\r\n– VL_CTA_FIN (Campo 10) – é igual ao somatório do valor total de código de aglutinação de todos os registros\r\ncujo campo código de aglutinação superior – COD_AGL_SUP (Campo 06) – é igual ao campo código de\r\naglutinação do registro J150 analisado, considerando o indicador da situação do valor total do código de\r\naglutinação – IND_DC_CTA_FIN (Campo 11). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_SALDO_COM_DRE]: Verifica, quando a identificação de moeda funcional –\r\n“IDENT_MF” (Campo 19) – do registro 0000 seja igual a “N” (Não), se o valor total – VL_CTA_FIN (Campo\r\n10) – das contas de maior detalhamento da Demonstração do Resultado do Exercício (DRE) – IND_COD_AGL\r\n(Campo 04) = “D” (Detalhe) – , considerando o código de aglutinação – COD_AGL (Campo 03) – é igual ao\r\nvalor do saldo calculado pelo programa para o mesmo código de aglutinação informado no registro I052. Se a\r\nregra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_SALDO_COM_DRE_MF]: Verifica, quando a identificação de moeda funcional –\r\n“IDENT_MF” (Campo 19) – do registro 0000 seja igual a “S” (Sim), se o valor total – VL_CTA_FIN (Campo\r\n10) – das contas de maior detalhamento da Demonstração do Resultado do Exercício (DRE) – IND_COD_AGL\r\n(Campo 04) = “D” (Detalhe) – , considerando o código de aglutinação – COD_AGL (Campo 03) – é igual ao\r\nvalor do saldo calculado pelo programa para o mesmo código de aglutinação informado no registro I052. Se a\r\nregra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_COD_AGL_DUPLICIDADE]: Verifica se o registro não é duplicado considerando a chave código\r\nde aglutinação das contas – “COD_AGL” (Campo 03) –, quando o campo tiver algum conteúdo. Se a regra não\r\nfor cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_I052]: Verifica, quando existe algum registro filho J150 com indicador de código\r\nde aglutinação – IND_COD_AGL (Campo 04) – igual a “D” (Detalhe), se existe um registro I052 com o mesmo\r\ncódigo de aglutinação, cujo registro I050 tenha o campo indicador do tipo de conta – IND_CTA (Campo 04) do\r\nregistro I050 – igual a “A” (Analítica). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_EXISTE_NOTA_EXPLICATIVA]: Verifica, quando existir, pelo menos, um registro J150 com o\r\ncampo referência à numeração das notas explicativas relativas às demonstrações contábeis – NOTA_EXP_REF\r\n(Campo 13) – preenchido – se existe um registro J800 com o campo tipo de documento TIPO_DOC (Campo 02)\r\ndo registro J800 – igual a “010 – Notas Explicativas”, “011 – Relatório da Administração”, “012 – Parecer dos\r\nAuditores” ou “999 – Outros”. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_I052_MESMO_GRUPO]: Verifica se a natureza da conta informada no registro\r\nI050 – COD_NAT (Campo 03) do registro I050 –, relacionada a código de aglutinação informado no registro\r\nI052 e constante no registro J150, corresponde ao grupo de contas que devem existir no registro J150 (Resultado).\r\nSe a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_SALDO_INI_DRE]: Verifica, caso o campo identificação das demonstrações do registro\r\nJ005 – J005.ID_DEM (Campo 04) – seja igual a “1” – Demonstrações contábeis da pessoa jurídica a que se\r\nrefere a escrituração – e o período das demonstrações (J005.DT_INI e J005.DT_FIN) esteja compreendido no\r\nperíodo da ECD (0000.DT_INI_ e 0000.DT_FIN), se o saldo final da linha do período imediatamente anterior –\r\nJ150.VL_CTA_INI (Campo 08) – é igual ao saldo final recuperado no registro C650 – C650.VL_CTA_FIN\r\n(Campo 06), considerando o indicador de saldo (D = Devedor ou C = Credor), para um mesmo código de\r\naglutinação (código de aglutinação do período imediatamente anterior igual ao código de aglutinação do período\r\natual). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_NU_ORDEM_DUPLICADO]: Verifica se todos os valores de número de ordem informados no registro J150 – J150.NU_ORDEM (Campo 02) – são diferentes. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_NIVEL_1_INEXISTENTE]: Verifica se existe nível “1” informado no registro J150 – J150.NIVEL_AGL (Campo 05). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OCO_UNICA_NIVEL_1]: Verifica se existe apenas uma linha com nível “1” no registro J150 – J150.NIVEL_AGL (Campo 05). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_EXISTE_IND_COD_AGLU_DETALHE]: Verifica se existe, pelo menos, um nível com indicador\r\nde código aglutinação – IND_COD_AGL (Campo 03) – igual a “D” (Detalhe) no registro J150. Se a regra não\r\nfor cumprida, o PGE do Sped Contábil gera um erro.\r\n'),
('02', 'COD_AGL', 'Código de aglutinação da Demonstração do Resultado (registro I052).', 'C', '008', NULL, NULL, 1, NULL, 3, '0:N', '[COD_AGL] (para [IND_VL] = P ou N)', '[REGRA_SOMA_NIVEIS_DRE]: Verifica, para cada registro J150 com indicador do tipo de código de\r\naglutinação – IND_COD_AGL (Campo 04) - igual a “T” (totalizador), se o valor total do código de aglutinação\r\n– VL_CTA_FIN (Campo 10) – é igual ao somatório do valor total de código de aglutinação de todos os registros\r\ncujo campo código de aglutinação superior – COD_AGL_SUP (Campo 06) – é igual ao campo código de\r\naglutinação do registro J150 analisado, considerando o indicador da situação do valor total do código de\r\naglutinação – IND_DC_CTA_FIN (Campo 11). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_SALDO_COM_DRE]: Verifica, quando a identificação de moeda funcional –\r\n“IDENT_MF” (Campo 19) – do registro 0000 seja igual a “N” (Não), se o valor total – VL_CTA_FIN (Campo\r\n10) – das contas de maior detalhamento da Demonstração do Resultado do Exercício (DRE) – IND_COD_AGL\r\n(Campo 04) = “D” (Detalhe) – , considerando o código de aglutinação – COD_AGL (Campo 03) – é igual ao\r\nvalor do saldo calculado pelo programa para o mesmo código de aglutinação informado no registro I052. Se a\r\nregra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_SALDO_COM_DRE_MF]: Verifica, quando a identificação de moeda funcional –\r\n“IDENT_MF” (Campo 19) – do registro 0000 seja igual a “S” (Sim), se o valor total – VL_CTA_FIN (Campo\r\n10) – das contas de maior detalhamento da Demonstração do Resultado do Exercício (DRE) – IND_COD_AGL\r\n(Campo 04) = “D” (Detalhe) – , considerando o código de aglutinação – COD_AGL (Campo 03) – é igual ao\r\nvalor do saldo calculado pelo programa para o mesmo código de aglutinação informado no registro I052. Se a\r\nregra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_COD_AGL_DUPLICIDADE]: Verifica se o registro não é duplicado considerando a chave código\r\nde aglutinação das contas – “COD_AGL” (Campo 03) –, quando o campo tiver algum conteúdo. Se a regra não\r\nfor cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_I052]: Verifica, quando existe algum registro filho J150 com indicador de código\r\nde aglutinação – IND_COD_AGL (Campo 04) – igual a “D” (Detalhe), se existe um registro I052 com o mesmo\r\ncódigo de aglutinação, cujo registro I050 tenha o campo indicador do tipo de conta – IND_CTA (Campo 04) do\r\nregistro I050 – igual a “A” (Analítica). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_EXISTE_NOTA_EXPLICATIVA]: Verifica, quando existir, pelo menos, um registro J150 com o\r\ncampo referência à numeração das notas explicativas relativas às demonstrações contábeis – NOTA_EXP_REF\r\n(Campo 13) – preenchido – se existe um registro J800 com o campo tipo de documento TIPO_DOC (Campo 02)\r\ndo registro J800 – igual a “010 – Notas Explicativas”, “011 – Relatório da Administração”, “012 – Parecer dos\r\nAuditores” ou “999 – Outros”. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_I052_MESMO_GRUPO]: Verifica se a natureza da conta informada no registro\r\nI050 – COD_NAT (Campo 03) do registro I050 –, relacionada a código de aglutinação informado no registro\r\nI052 e constante no registro J150, corresponde ao grupo de contas que devem existir no registro J150 (Resultado).\r\nSe a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_SALDO_INI_DRE]: Verifica, caso o campo identificação das demonstrações do registro\r\nJ005 – J005.ID_DEM (Campo 04) – seja igual a “1” – Demonstrações contábeis da pessoa jurídica a que se\r\nrefere a escrituração – e o período das demonstrações (J005.DT_INI e J005.DT_FIN) esteja compreendido no\r\nperíodo da ECD (0000.DT_INI_ e 0000.DT_FIN), se o saldo final da linha do período imediatamente anterior –\r\nJ150.VL_CTA_INI (Campo 08) – é igual ao saldo final recuperado no registro C650 – C650.VL_CTA_FIN\r\n(Campo 06), considerando o indicador de saldo (D = Devedor ou C = Credor), para um mesmo código de\r\naglutinação (código de aglutinação do período imediatamente anterior igual ao código de aglutinação do período\r\natual). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_NU_ORDEM_DUPLICADO]: Verifica se todos os valores de número de ordem informados no registro J150 – J150.NU_ORDEM (Campo 02) – são diferentes. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_NIVEL_1_INEXISTENTE]: Verifica se existe nível “1” informado no registro J150 – J150.NIVEL_AGL (Campo 05). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OCO_UNICA_NIVEL_1]: Verifica se existe apenas uma linha com nível “1” no registro J150 – J150.NIVEL_AGL (Campo 05). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_EXISTE_IND_COD_AGLU_DETALHE]: Verifica se existe, pelo menos, um nível com indicador\r\nde código aglutinação – IND_COD_AGL (Campo 03) – igual a “D” (Detalhe) no registro J150. Se a regra não\r\nfor cumprida, o PGE do Sped Contábil gera um erro.\r\n'),
