INSERT INTO `bloco_j930` (`num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
('01', 'REG', 'Texto fixo contendo \"J930\".', 'C', '004', NULL, '\"J930\"', 1, NULL, 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('02', 'IDENT_NOM', 'Nome do signatário.', 'C', NULL, NULL, NULL, 1, NULL, 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('03', 'IDENT_CPF_CNPJ', 'CPF ou CNPJ do signatário.', 'N', '11 ou 14', NULL, NULL, 1, '[REGRA_VALIDA_CPF]: Verifica se a regra de formação do CPF – IDENT_CPF_CNPJ (Campo 03) – é válida. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_CNPJ]: Verifica se a regra de formação do CNPJ – IDENT_CPF_CNPJ (Campo 03) – é\r\nválida. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('04', 'IDENT_QUALIF', 'Qualificação do assinante, conforme tabela.', 'C', NULL, NULL, NULL, 1, '[REGRA_TABELA_ASSINANTE_DESC]: Caso o código de qualificação do assinante – COD_ASSIN\r\n(Campo 05) – seja igual a 900 (Contador ou Contabilista), verifica se a descrição informada no campo IDENT_QUALIF (Campo 04) corresponde a Contador ou Contabilista. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n', 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('05', 'COD_ASSIN', 'Código de qualificação do assinante, conforme tabela.', 'C', '003', NULL, NULL, 1, '[REGRA_QUALIF_INV_RESP_LEGAL]: Verifica se o código de qualificação do assinante – COD_ASSIN\r\n(Campo 05) – é diferente de “900”, quando a identificação do signatário que será validado como responsável pela assinatura da ECD – IND_RESP_LEGAL (Campo 12) – for igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n', 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('06', 'IND_CRC', 'Número de inscrição do contador no Conselho Regional de Contabilidade.', 'C', NULL, NULL, NULL, 0, '[REGRA_OBRIGATORIO_CONTADOR]: Verifica se os campos número de inscrição do contabilista no\r\nConselho Regional de Contabilidade – IND_CRC (Campo 06) –, e-mail do signatário – EMAIL (Campo 07) –, telefone do signatário – FONE (Campo 08) – e indicação do CRC expedidor – UF_CRC (Campo 09) – foram preenchidos quando o código de qualificação do assinante – COD_ASSIN (Campo 05) – for igual a 900 (Contador ou Contabilista). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('07', 'EMAIL', 'Endereço de e-mail do signatário.', 'C', '060', NULL, NULL, 0, '[REGRA_OBRIGATORIO_CONTADOR]: Verifica se os campos número de inscrição do contabilista no\r\nConselho Regional de Contabilidade – IND_CRC (Campo 06) –, e-mail do signatário – EMAIL (Campo 07) –, telefone do signatário – FONE (Campo 08) – e indicação do CRC expedidor – UF_CRC (Campo 09) – foram preenchidos quando o código de qualificação do assinante – COD_ASSIN (Campo 05) – for igual a 900 (Contador ou Contabilista). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '\r\n[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('08', 'FONE', 'Telefone do signatário.', 'C', '014', NULL, NULL, 0, '[REGRA_OBRIGATORIO_CONTADOR]: Verifica se os campos número de inscrição do contabilista no\r\nConselho Regional de Contabilidade – IND_CRC (Campo 06) –, e-mail do signatário – EMAIL (Campo 07) –,\r\ntelefone do signatário – FONE (Campo 08) – e indicação do CRC expedidor – UF_CRC (Campo 09) – foram preenchidos quando o código de qualificação do assinante – COD_ASSIN (Campo 05) – for igual a 900 (Contador ou Contabilista). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '\r\n[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('09', 'UF_CRC', 'Indicação da unidade da federação que expediu o CRC.', 'C', '002', NULL, NULL, 0, '[REGRA_TABELA_UF] : Verifica se o código informado da Unidade da Federação – UF_CRC (Campo 09) –\r\nexiste na Tabela de Unidades da Federação. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_OBRIGATORIO_CONTADOR] : Verifica se os campos número de inscrição do contabilista no\r\nConselho Regional de Contabilidade – IND_CRC (Campo 06) –, e-mail do signatário – EMAIL (Campo 07) –,\r\ntelefone do signatário – FONE (Campo 08) – e indicação do CRC expedidor – UF_CRC (Campo 09) – fo', 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '\r\n[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('10', 'NUM_SEQ_CRC', 'Número da Certidão de Regularidade Profissional do Contador no formato UF/ano/número.', 'C', NULL, NULL, NULL, 0, '[REGRA_VALIDA_FORMATO_SEQUENCIAL_CRC] : Verifica se o formato do campo número sequencial\r\n– NUM_SEQ_CRC (Campo 10) – é UF/YYYY/NÚMERO, onde UF deve existir na Tabela de Unidades da\r\nFederação e yyyy corresponde ao ano. Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.\r\n[REGRA_ADVERTENCIA_CONTADOR] : Verifica se os campos número da certidão de regularidade –\r\nNUM_SEQ_CRC (Campo 10) – e data de validade da certidão – DT_CRC (Campo 11) – foram preenchidos\r\nquando o código de qualif', 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '\r\n[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('11', 'DT_CRC', 'Data de validade da Certidão de Regularidade Profissional do Contador.', 'N', '008', NULL, NULL, 0, '[REGRA_ADVERTENCIA_CONTADOR] : Verifica se os campos número da certidão de regularidade –\r\nNUM_SEQ_CRC (Campo 10) – e data de validade da certidão – DT_CRC (Campo 11) – foram preenchidos\r\nquando o código de qualificação do assinante – COD_ASSIN (Campo 05) – for igual a 900 (Contador ou Contabilista). Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.\r\n[REGRA_AVISO_ASSIN_CNPJ]: : Verifica, quando o campo código do assinante – COD_ASSIN (Campo 05)\r\n– for igual a “001 – Pessoa Juríd', 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '\r\n[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('12', 'IND_RESP_LEGAL', 'Identificação do signatário que será validado como responsável legal pela assinatura da ECD. Valores possíveis: S – Sim; N – Não.', 'C', '001', NULL, '[S,N]', 1, NULL, 3, '1:N', '[IDENT_CPF_CNPJ]+[COD_ASSIN]', '\r\n[REGRA_OBRIGATORIO_ASSIN_CONTADOR]: Verifica se existe, no mínimo, um registro J930 cujo\r\ncódigo de qualificação do assinante – COD_ASSIN (Campo 05) – seja igual a 900 (Contador ou Contabilista) e,\r\nno mínimo, um registro J930 cujo código de qualificação do assinante – COD_ASSIN (Campo 05) – seja\r\ndiferente de 900. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ +\r\nCOD_ASSIN). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_OBRIGATORIO_UM_RESP_LEGAL]: Verifica se existe um registro J930 com a identificação do\r\nsignatário que será validado como responsável legal pela assinatura da ECD – IND_RESP_LEGAL (Campo 12)\r\n– igual a “S” (Sim). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');

