-- Estrutura para tabela `bloco_j932`
--

DROP TABLE IF EXISTS `bloco_j932`;
CREATE TABLE IF NOT EXISTS `bloco_j932` (
  `num` char(2) NOT NULL,
  `campo` varchar(50) NOT NULL,
  `descricao` text NOT NULL,
  `tipo` char(1) NOT NULL,
  `tamanho` varchar(20) DEFAULT NULL,
  `decimal` smallint DEFAULT NULL,
  `valores_validos` varchar(500) DEFAULT NULL,
  `obrigatorio` tinyint(1) NOT NULL DEFAULT '1',
  `regras_validacao` varchar(500) DEFAULT NULL,
  `nivel_hierarquico` tinyint DEFAULT NULL,
  `ocorrencia` varchar(10) DEFAULT NULL,
  `campos_chave` varchar(255) DEFAULT NULL,
  `regras_registro` text,
  PRIMARY KEY (`num`,`campo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

