INSERT INTO `bloco_j932` (`num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
('01', 'REG', 'Texto fixo contendo \"J932\".', 'C', '004', NULL, '[\"J932\"]', 1, NULL, 3, '0:2', '[IDENT_CPF_CNPJ_T]+[COD_ASSIN_T]', '[REGRA_OBRIGATORIO_CONTADOR_ASS_TERMO]: Verifica se existe, no mínimo, um registro J932\r\ncujo código de qualificação do assinante do termo – COD_ASSIN_T (Campo 05) – seja igual a 910 (Contador\r\nou Contabilista Responsável Pelo Termo de Verificação par Fins de Substituição da ECD). Se a regra não for\r\ncumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ_T +\r\nCOD_ASSIN_T). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('02', 'IDENT_NOM_T', 'Nome do signatário do termo de verificação.', 'C', NULL, NULL, NULL, 1, NULL, 3, '0:2', '[IDENT_CPF_CNPJ_T]+[COD_ASSIN_T]', '[REGRA_OBRIGATORIO_CONTADOR_ASS_TERMO]: Verifica se existe, no mínimo, um registro J932\r\ncujo código de qualificação do assinante do termo – COD_ASSIN_T (Campo 05) – seja igual a 910 (Contador\r\nou Contabilista Responsável Pelo Termo de Verificação par Fins de Substituição da ECD). Se a regra não for\r\ncumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ_T +\r\nCOD_ASSIN_T). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('03', 'IDENT_CPF_CNPJ_T', 'CPF ou CNPJ do assinante do termo de verificação.', 'N', 'CPF(11) ou CNPJ(14)', NULL, NULL, 1, '[REGRA_VALIDA_CPF] : Verifica se a regra de formação do CPF – IDENT_CPF_CNPJ_T (Campo 03) – é válida. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_VALIDA_CNPJ]: Verifica se a regra de formação do CNPJ – IDENT_CPF_CNPJ_T (Campo 03) – é válida. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '0:2', '[IDENT_CPF_CNPJ_T]+[COD_ASSIN_T]', '[REGRA_OBRIGATORIO_CONTADOR_ASS_TERMO]: Verifica se existe, no mínimo, um registro J932\r\ncujo código de qualificação do assinante do termo – COD_ASSIN_T (Campo 05) – seja igual a 910 (Contador\r\nou Contabilista Responsável Pelo Termo de Verificação par Fins de Substituição da ECD). Se a regra não for\r\ncumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ_T +\r\nCOD_ASSIN_T). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('04', 'IDENT_QUALIF_T', 'Qualificação do assinante do termo de verificação, conforme tabela.', 'C', NULL, NULL, NULL, 1, '[REGRA_TABELA_ASSINANTE_DESC]: Caso o código de qualificação do assinante – COD_ASSIN_T\r\n(Campo 05) – seja igual a 910 (Contador/Contabilista Responsável Pelo Termo de Verificação para Fins de Substituição da ECD), verifica se a descrição informada no campo IDENT_QUALIF_T (Campo 04) corresponde\r\na Contador/Contabilista Responsável Pelo Termo de Verificação para Fins de Substituição da ECD. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '0:2', '[IDENT_CPF_CNPJ_T]+[COD_ASSIN_T]', '[REGRA_OBRIGATORIO_CONTADOR_ASS_TERMO]: Verifica se existe, no mínimo, um registro J932\r\ncujo código de qualificação do assinante do termo – COD_ASSIN_T (Campo 05) – seja igual a 910 (Contador\r\nou Contabilista Responsável Pelo Termo de Verificação par Fins de Substituição da ECD). Se a regra não for\r\ncumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ_T +\r\nCOD_ASSIN_T). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('05', 'COD_ASSIN_T', 'Código de qualificação do assinante do termo de verificação, conforme tabela.', 'C', '003', NULL, NULL, 1, '[REGRA_QUALIF_INVALIDA_ASS_TERMO]: Verifica, quando o campo CPF/CNPJ do assinante do termo\r\n– IDENT_CPF_CNPJ_T (Campo 03) – é igual a um CNPJ, se o campo código do assinante do termo –\r\nCOD_ASSIN (Campo 05) – é igual a “920” (Auditor Independente Responsável pelo Termo de Verificação para Fins de Substituição da ECD). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '0:2', '[IDENT_CPF_CNPJ_T]+[COD_ASSIN_T]', '[REGRA_OBRIGATORIO_CONTADOR_ASS_TERMO]: Verifica se existe, no mínimo, um registro J932\r\ncujo código de qualificação do assinante do termo – COD_ASSIN_T (Campo 05) – seja igual a 910 (Contador\r\nou Contabilista Responsável Pelo Termo de Verificação par Fins de Substituição da ECD). Se a regra não for\r\ncumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ_T +\r\nCOD_ASSIN_T). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('06', 'IND_CRC_T', 'Número de inscrição do contabilista no Conselho Regional de Contabilidade.', 'C', NULL, NULL, NULL, 0, '[REGRA_OBRIGATORIO_ASS_TERMO]: Verifica se os campos número de inscrição do contabilista no\r\nConselho Regional de Contabilidade – IND_CRC_T (Campo 06) –, e-mail do signatário – EMAIL_T (Campo\r\n07) –, telefone do signatário – FONE_T (Campo 08) – e indicação do CRC expedidor – UF_CRC_T (Campo\r\n09) – foram preenchidos quando o código de qualificação do assinante do termo de verificação – COD_ASSIN_T (Campo 05) – for igual a 910 (Contador/Contabilista Responsável Pelo Termo de Verificação para Fins ', 3, '0:2', '[IDENT_CPF_CNPJ_T]+[COD_ASSIN_T]', '[REGRA_OBRIGATORIO_CONTADOR_ASS_TERMO]: Verifica se existe, no mínimo, um registro J932\r\ncujo código de qualificação do assinante do termo – COD_ASSIN_T (Campo 05) – seja igual a 910 (Contador\r\nou Contabilista Responsável Pelo Termo de Verificação par Fins de Substituição da ECD). Se a regra não for\r\ncumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ_T +\r\nCOD_ASSIN_T). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
('07', 'EMAIL_T', 'Email do signatário.', 'C', '060', NULL, NULL, 0, '[REGRA_OBRIGATORIO_ASS_TERMO]: Verifica se os campos número de inscrição do contabilista no\r\nConselho Regional de Contabilidade – IND_CRC_T (Campo 06) –, e-mail do signatário – EMAIL_T (Campo\r\n07) –, telefone do signatário – FONE_T (Campo 08) – e indicação do CRC expedidor – UF_CRC_T (Campo\r\n09) – foram preenchidos quando o código de qualificação do assinante do termo de verificação – COD_ASSIN_T (Campo 05) – for igual a 910 (Contador/Contabilista Responsável Pelo Termo de Verificação para Fins ', 3, '0:2', '[IDENT_CPF_CNPJ_T]+[COD_ASSIN_T]', '[REGRA_OBRIGATORIO_CONTADOR_ASS_TERMO]: Verifica se existe, no mínimo, um registro J932\r\ncujo código de qualificação do assinante do termo – COD_ASSIN_T (Campo 05) – seja igual a 910 (Contador\r\nou Contabilista Responsável Pelo Termo de Verificação par Fins de Substituição da ECD). Se a regra não for\r\ncumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_IDENT_CPF_CNPJ_COD_ASSIN_DUPLICIDADE]: Verifica se o registro não é duplicado\r\nconsiderando a chave CPF ou CNPJ e código de identificação do assinante (IDENT_CPF_CNPJ_T +\r\nCOD_ASSIN_T). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
