-- Despejando dados para a tabela `bloco_k030`
--

INSERT INTO `bloco_k030` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"K030\".', 'C', '004', NULL, '\"K030\"', 1, NULL, 2, ' 0:1', '[DT_INI_CONS]', '[REGRA_OBRIGATORIO_K030]:Verifica se o registro está preenchido quando o indicador de escriturações contábeis consolidadas – IND_ESC_CONS (Campo 20) – do registro 0000 for igual a “S” (Sim) e o mês da data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000 for igual a 12 (dezembro).\r\nCaso contrário, o registro K030 não deve existir. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n'),
(2, '02', 'DT_INI', 'Data inicial do período consolidado.', 'N', '008', NULL, NULL, 1, NULL, 2, '0:1', '[DT_INI_CONS]\r\n', '[REGRA_OBRIGATORIO_K030]:Verifica se o registro está preenchido quando o indicador de escriturações contábeis consolidadas – IND_ESC_CONS (Campo 20) – do registro 0000 for igual a “S” (Sim) e o mês da data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000 for igual a 12 (dezembro).\r\nCaso contrário, o registro K030 não deve existir. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n'),
(3, '03', 'DT_FIN', 'Data final do período consolidado.', 'N', '008', NULL, NULL, 1, '[REGRA_DATA_MAIOR_INICIAL_CONS]:Verifica se a data final do período consolidado – DT_FIN\r\n(Campo 03) – é maior ou igual a data inicial do período consolidado – DT_INI (Campo 02). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_IGUAL_DT_FIN_REG0000]:Verifica se a data final do período consolidado – DT_FIN (Campo 03)\r\n– é igual à data final das informações contidas no arquivo – DT_FIN (Campo 04) do registro 0000. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_PERIODO_CONS]:Verifica se a diferença entre a data final do período consolidado – DT_FIN\r\n(Campo 03) – e a data inicial do período consolidado – DT_INI (Campo 02) – é menor ou igual a 1 (um) ano.Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 2, '0:1', '[DT_INI_CONS]\r\n', '[REGRA_OBRIGATORIO_K030]:Verifica se o registro está preenchido quando o indicador de escriturações contábeis consolidadas – IND_ESC_CONS (Campo 20) – do registro 0000 for igual a “S” (Sim) e o mês da data final das informações contidas no arquivo – DT_FIN (Campo 04) – do registro 0000 for igual a 12 (dezembro).\r\nCaso contrário, o registro K030 não deve existir. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');

