-- Despejando dados para a tabela `bloco_k100`
--

INSERT INTO `bloco_k100` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `casas_decimais`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"K100\".', 'C', '004', NULL, '\"K100\"', 1, NULL, 3, '0:N', '[EMP_COD]\r\n', '[REGRA_REGISTRO_OBRIGATORIO_K110]: Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “S” (Sim), se existe, pelo menos, um registro K110 preenchido. Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “N” (Não), se não existe registros K110. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_OBRIGATORIO_K100_CNPJ_0000]: Verifica se existe um registro K100 com o campo “CNPJ” (Campo 04) igual ao campo “CNPJ” (Campo 06) do registro 0000. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.'),
(2, '02', 'COD_PAIS', 'Código do país da empresa, conforme tabela do Banco Central do Brasil.', 'N', '005', NULL, 'Tabela externa PAIS_SISCOMEX', 1, '[REGRA_TABELA_PAISES]:Verifica se o código do país da empresa – COD_PAIS (Campo 02) – consta na\r\ntabela de países. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro', 3, '0:N', '[EMP_COD]\r\n', '[REGRA_REGISTRO_OBRIGATORIO_K110]: Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “S” (Sim), se existe, pelo menos, um registro K110 preenchido. Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “N” (Não), se não existe registros K110. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_OBRIGATORIO_K100_CNPJ_0000]: Verifica se existe um registro K100 com o campo “CNPJ” (Campo 04) igual ao campo “CNPJ” (Campo 06) do registro 0000. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.'),
(3, '03', 'EMP_COD', 'Código de identificação da empresa participante.', 'N', '004', NULL, NULL, 1, NULL, 3, '0:N', '[EMP_COD]\r\n', '[REGRA_REGISTRO_OBRIGATORIO_K110]: Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “S” (Sim), se existe, pelo menos, um registro K110 preenchido. Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “N” (Não), se não existe registros K110. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_OBRIGATORIO_K100_CNPJ_0000]: Verifica se existe um registro K100 com o campo “CNPJ”(Campo 04) igual ao campo “CNPJ” (Campo 06) do registro 0000. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.'),
(4, '04', 'CNPJ', 'CNPJ (somente os 8 primeiros dígitos).', 'N', '008', NULL, NULL, 0, '[REGRA_OBRIGATORIO_CNPJ_BRASIL]:Verifica, quando o campo CNPJ (Campo 04) está preenchido,se o código do país da empresa – COD_PAIS (Campo 02) – está preenchido com o código correspondente a “Brasil”. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro', 3, '0:N', '[EMP_COD]\r\n', '[REGRA_REGISTRO_OBRIGATORIO_K110]: Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “S” (Sim), se existe, pelo menos, um registro K110 preenchido. Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “N” (Não), se não existe registros K110. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_OBRIGATORIO_K100_CNPJ_0000]: Verifica se existe um registro K100 com o campo “CNPJ”(Campo 04) igual ao campo “CNPJ” (Campo 06) do registro 0000. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.'),
(5, '05', 'NOME', 'Nome empresarial.', 'C', NULL, NULL, NULL, 1, NULL, 3, '0:N', '[EMP_COD]\r\n', '[REGRA_REGISTRO_OBRIGATORIO_K110]: Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “S” (Sim), se existe, pelo menos, um registro K110 preenchido. Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “N” (Não), se não existe registros K110. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_OBRIGATORIO_K100_CNPJ_0000]: Verifica se existe um registro K100 com o campo “CNPJ”(Campo 04) igual ao campo “CNPJ” (Campo 06) do registro 0000. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.'),
(6, '06', 'PER_PART', 'Percentual de participação total do conglomerado na empresa no final do período consolidado. Observação: informar o percentual de participação acionária da empresa titular da ECD.', 'N', '008', '004', NULL, 1, '[REGRA_PERC_MENOR_IGUAL_100]:Verifica se o percentual de participação total do conglomerado na\r\nempresa no final do período consolidado – PER_PART (Campo 06) – ou o percentual de consolidação da\r\nempresa no final do período consolidado – PER_CONS (Campo 08) – é menor ou igual a 100. Se a regra não\r\nfor cumprida, o PGE do Sped Contábil gera um erro. [REGRA_MAIOR_IGUAL_ZERO]:: Verifica se o percentual de participação total do conglomerado na empresa\r\nno final do período consolidado – PER_PART (Campo 06) – ou o percentual de consolidação da empresa no\r\nfinal do período consolidado – PER_CONS (Campo 08) – é maior ou igual a zero. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n', 3, '0:N', '[EMP_COD]\r\n', '[REGRA_REGISTRO_OBRIGATORIO_K110]: Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “S” (Sim), se existe, pelo menos, um registro K110 preenchido. Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “N” (Não), se não existe registros K110. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_OBRIGATORIO_K100_CNPJ_0000]: Verifica se existe um registro K100 com o campo “CNPJ”(Campo 04) igual ao campo “CNPJ” (Campo 06) do registro 0000. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.'),
(7, '07', 'EVENTO', 'Evento societário ocorrido no período: S - Sim / N - Não.', 'C', '001', NULL, '[S;N]', 1, NULL, 3, '0:N', '[EMP_COD]\r\n', '[REGRA_REGISTRO_OBRIGATORIO_K110]: Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “S” (Sim), se existe, pelo menos, um registro K110 preenchido. Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “N” (Não), se não existe registros K110. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_OBRIGATORIO_K100_CNPJ_0000]: Verifica se existe um registro K100 com o campo “CNPJ”(Campo 04) igual ao campo “CNPJ” (Campo 06) do registro 0000. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.'),
(8, '08', 'PER_CONS', 'Percentual de consolidação da empresa no final do período consolidado: percentual do resultado da empresa que foi para a consolidação.', 'N', '008', '004', NULL, 1, '[REGRA_PERC_MENOR_IGUAL_100]: Verifica se o percentual de participação total do conglomerado na\r\nempresa no final do período consolidado – PER_PART (Campo 06) – ou o percentual de consolidação da\r\nempresa no final do período consolidado – PER_CONS (Campo 08) – é menor ou igual a 100. Se a regra não\r\nfor cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_MAIOR_IGUAL_ZERO]: Verifica se o percentual de participação total do conglomerado na empresa\r\nno final do período consolidado – PER_PART (Campo 06) – ou o percentual de consolidação da empresa no\r\nfinal do período consolidado – PER_CONS (Campo 08) – é maior ou igual a zero. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '0:N', '[EMP_COD]', '[REGRA_REGISTRO_OBRIGATORIO_K110]: Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “S” (Sim), se existe, pelo menos, um registro K110 preenchido. Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “N” (Não), se não existe registros K110. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_OBRIGATORIO_K100_CNPJ_0000]: Verifica se existe um registro K100 com o campo “CNPJ”(Campo 04) igual ao campo “CNPJ” (Campo 06) do registro 0000. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.'),
(9, '09', 'DATA_INI_EMP', 'Data inicial do período da escrituração contábil da empresa que foi consolidada.', 'N', '008', NULL, NULL, 1, '[REGRA_CONSOLIDADA_INICIO_DIFERENTE]: : Verifica se a data inicial do período da escrituração\r\ncontábil da empresa que foi consolidada – DATA_INI_EMP (Campo 09) – é igual à data inicial do período\r\nconsolidado – DT_INI (Campo 02) – do registro K030. Se a regra não for cumprida, o PGE do Sped Contábil\r\ngera um aviso.\r\n- Se a data inicial do período da escrituração contábil da empresa que foi consolidada –\r\nDATA_INI_EMP (Campo 09) – for maior que a data inicial do período consolidado – DT_INI (Campo\r\n02) do registro K030, o PGE do Sped Contábil gera um aviso.\r\n- Se a data inicial do período da escrituração contábil da empresa que foi consolidada –\r\nDATA_INI_EMP (Campo 09) – for menor que a data inicial do período consolidado – DT_INI (Campo\r\n02) do registro K030, o PGE do Sped Contábil gera um aviso.\r\n[REGRA_ANO_IGUAL_ANTERIOR_K030]: Verifica se o ano da data inicial do período da escrituração\r\ncontábil da empresa consolidada – DT_INI_EMP (Campo 09) – é igual ao ano da data inicial infor', 3, '0:N', '[EMP_COD]\r\n', '[REGRA_REGISTRO_OBRIGATORIO_K110]: Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “S” (Sim), se existe, pelo menos, um registro K110 preenchido. Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “N” (Não), se não existe registros K110. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_OBRIGATORIO_K100_CNPJ_0000]: Verifica se existe um registro K100 com o campo “CNPJ”(Campo 04) igual ao campo “CNPJ” (Campo 06) do registro 0000. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.'),
(10, '10', 'DATA_FIN_EMP', 'Data final do período da escrituração contábil da empresa que foi consolidada.', 'N', '008', NULL, NULL, 1, '[REGRA_DATA_FIN_MAIOR_IGUAL]: Verifica se a data final da escrituração contábil da empresa que foi\r\nconsolidada – “DT_FIN_EMP” (Campo 10) – é maior ou igual à data inicial da escrituração contábil da empresa que foi consolidada – “DT_INI_EMP” (Campo 09). Se a regra não for cumprida, o PGE do Sped Contábil gera\r\num erro.\r\n [REGRA_CONSOLIDADA_FINAL_DIFERENTE]:Verifica se a data final da escrituração contábil da\r\nempresa que foi consolidada – “DT_FIN_EMP” (Campo 10) – é igual à data final do período consolidado –\r\n“DT_FIN” (Campo 03) – do registro K030.\r\n- Se a data final da escrituração contábil da empresa que foi consolidada – “DT_FIN_EMP” (Campo\r\n10) – for menor que a data final do período consolidado – “DT_FIN” (Campo 03) – do registro K030,o PGE do Sped Contábil gera um aviso.\r\n- Se a data final da escrituração contábil da empresa que foi consolidada – “DT_FIN_EMP” (Campo\r\n10) – for maior que a data final do período consolidado – “DT_FIN” (Campo 03) – do registro K030, o PGE do Sped ', 3, '0:N', '[EMP_COD]\r\n', '[REGRA_REGISTRO_OBRIGATORIO_K110]: Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “S” (Sim), se existe, pelo menos, um registro K110 preenchido. Verifica, quando o evento societário ocorrido no período – “EVENTO” (Campo 07) – for igual a “N” (Não), se não existe registros K110. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_OBRIGATORIO_K100_CNPJ_0000]: Verifica se existe um registro K100 com o campo “CNPJ”(Campo 04) igual ao campo “CNPJ” (Campo 06) do registro 0000. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.');

