-- Despejando dados para a tabela `bloco_k110`
--

INSERT INTO `bloco_k110` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"K110\".', 'C', '004', NULL, '\"K110\"', 1, NULL, 4, '0:N', NULL, '[REGRA_REGISTRO_OBRIGATORIO_K115]: Verifica se existe, pelo menos, um registro K115, quando o campo EVENTO estiver preenchido com “1” (Aquisição), “2” (Alienação), “3” (Fusão), “4” (Cisão Parcial), “5” (Cisão Total) ou “6” (Incorporação). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_REGISTRO_NAO_DEVE_EXISTIR_K115]: Verifica se não existe registro K115, quando o campo EVENTO estiver preenchido com “7” (Extinção) ou “8” (Constituição). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_SOMATORIO_PER_EVT_K115]: Verifica se o somatório de todos os percentuais das empresas participantes envolvidas na operação – PER_EVT (Campo 04) – dos registros K115 é menor ou igual a 100. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(2, '02', 'EVENTO', 'Evento societário ocorrido no período: 1 – Aquisição; 2 – Alienação; 3 – Fusão; 4 – Cisão Parcial; 5 – Cisão Total; 6 – Incorporação; 7 – Extinção; 8 – Constituição.', 'N', '001', NULL, '[1;2;3;4;5;6;7;8]', 1, NULL, 4, '0:N', NULL, '[REGRA_REGISTRO_OBRIGATORIO_K115]: Verifica se existe, pelo menos, um registro K115, quando o campo EVENTO estiver preenchido com “1” (Aquisição), “2” (Alienação), “3” (Fusão), “4” (Cisão Parcial), “5” (Cisão Total) ou “6” (Incorporação). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_REGISTRO_NAO_DEVE_EXISTIR_K115]: Verifica se não existe registro K115, quando o campo EVENTO estiver preenchido com “7” (Extinção) ou “8” (Constituição). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_SOMATORIO_PER_EVT_K115]: Verifica se o somatório de todos os percentuais das empresas participantes envolvidas na operação – PER_EVT (Campo 04) – dos registros K115 é menor ou igual a 100. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(3, '03', 'DT_EVENTO', 'Data do evento societário.', 'N', '008', NULL, NULL, 1, '[REGRA_ANO_IGUAL_ANTERIOR_POSTERIOR_K030]: Verifica se ano a data do evento societário –\r\nDT_EVENTO (Campo 03) – é igual ao ano da data final do período consolidado – DT_FIN (Campo 03) – do\r\nregistro K030, ou o ano anterior ou o ano posterior. Se a regra não for cumprida, o PGE do Sped Contábil gera\r\num erro.', 4, '0:N', NULL, '[REGRA_REGISTRO_OBRIGATORIO_K115]: Verifica se existe, pelo menos, um registro K115, quando o campo EVENTO estiver preenchido com “1” (Aquisição), “2” (Alienação), “3” (Fusão), “4” (Cisão Parcial), “5” (Cisão Total) ou “6” (Incorporação). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_REGISTRO_NAO_DEVE_EXISTIR_K115]: Verifica se não existe registro K115, quando o campo EVENTO estiver preenchido com “7” (Extinção) ou “8” (Constituição). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_SOMATORIO_PER_EVT_K115]: Verifica se o somatório de todos os percentuais das empresas participantes envolvidas na operação – PER_EVT (Campo 04) – dos registros K115 é menor ou igual a 100. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');

