INSERT INTO `bloco_k115` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"K115\".', 'C', '004', NULL, '\"K115\"', 1, NULL, 5, '0:N', NULL, NULL),
(2, '02', 'EMP_COD_PART', 'Código da empresa envolvida na operação.', 'N', '004', NULL, NULL, 1, '[REGRA_EXISTE_EMP_COD_K100]: Verifica se o código da empresa envolvida na operação –\r\nEMP_COD_PART (Campo 02) – foi informado no registro K100, no campo código de identificação da empresa\r\nparticipante – EMP_COD (Campo 03). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n', 5, '0:N', NULL, NULL),
(3, '03', 'COND_PART', 'Condição da empresa relacionada à operação: 1 – Sucessora; 2 – Adquirente; 3 – Alienante.', 'N', '001', NULL, '[1;2;3]', 1, '[REGRA_CONDICAO_COMPATIVEL]: Verifica:\r\n- Quando a condição da empresa relacionada à operação – COND_PART (Campo 03) – for igual a “1”\r\n(Sucessora), se o evento societário ocorrido no período – EVENTO (Campo 02) – do registro K110 foi\r\npreenchido como “3” (Fusão), “4” (Cisão Parcial), “5” (Cisão Total) ou “6” (Incorporação). - Quando a condição da empresa relacionada à operação – COND_PART (Campo 03) – for igual a “2”\r\n(Adquirente) se o evento societário ocorrido no período – EVENTO (Campo 02) – do registro K110 foi\r\npreenchido como “1” (Aquisição).\r\n- Quando a condição da empresa relacionada à operação – COND_PART (Campo 03) – for igual a “3”\r\n(Alienante), se o evento societário ocorrido no período – EVENTO (Campo 02) – do registro K110 foi\r\npreenchido como “2” (Alienação).\r\nSe as regras não forem cumpridas, o PGE do Sped Contábil gera um erro.', 5, '0:N', NULL, NULL),
(4, '04', 'PER_EVT', 'Percentual da empresa participante envolvida na operação.', 'N', '008', '004', NULL, 1, '[REGRA_PERC_MENOR_IGUAL_100]:Verifica se o percentual da empresa participante envolvida na\r\noperação – PER_EVT (Campo 04) – é menor ou igual a 100. Se a regra não for cumprida, o PGE do Sped\r\nContábil gera um erro.', 5, '0:N', NULL, NULL);

