INSERT INTO `bloco_k200` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"K200\".', 'C', '004', NULL, '\"K200\"', 1, NULL, 3, '1:N', '[COD_CTA]', NULL),
(2, '02', 'COD_NAT', 'Código da natureza da conta/grupo de contas, conforme tabela publicada pelo Sped.', 'C', '002', NULL, NULL, 1, '[REGRA_TABELA_NATUREZA]: Verifica se o código da natureza da conta/grupo de contas – COD_NAT\r\n(Campo 03) – existe na Tabela de Naturezas das Contas/Grupo de Contas. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n', 3, '1:N', '[COD_CTA]', NULL),
(3, '03', 'IND_CTA', 'Indicador do tipo de conta: S - Sintética (grupo de contas); A - Analítica (conta).', 'C', '001', NULL, '[S;A]', 1, NULL, 3, '1:N', '[COD_CTA]', NULL),
(4, '04', 'NIVEL', 'Nível da conta.', 'N', NULL, NULL, NULL, 1, '[REGRA_MAIOR_QUE_UM]: Verifica se o nível da conta – NIVEL (Campo 04) – é maior ou igual a 1. Se a\r\nregra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n[REGRA_ANALITICA_NIVEL_2]: Verifica, quando o indicador do tipo de conta – IND_CTA (Campo 03) –\r\né igual a “A” (Analítica) e o código da natureza da conta/grupo de contas – COD_NAT (Campo 02) – é igual a “01” (Ativo), “02” (Passivo), “03” (Patrimônio Líquido) ou “04” (Contas de Resultado), se o nível da conta – “NIVEL” (Campo 04) – é maior que 2. Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.', 3, '1:N', '[COD_CTA]', NULL),
(5, '05', 'COD_CTA', 'Código da conta.', 'C', NULL, NULL, NULL, 1, NULL, 3, '1:N', '[COD_CTA]', NULL),
(6, '06', 'COD_CTA_SUP', 'Código da conta superior.', 'C', NULL, NULL, NULL, 0, '[REGRA_COD_CTA_SUP_OBRIGATORIO]:Verifica se o nível da conta – NIVEL (Campo 04) – é maior\r\nque 1. Se afirmativo executa a REGRA_CAMPO_OBRIGATORIO. Se a regra não for cumprida, o PGE do\r\nSped Contábil gera um erro.\r\nREGRA_CAMPO_OBRIGATORIO: Verifica se o campo foi preenchido com algum valor diferente\r\nde vazio e do caractere “espaço”. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.[REGRA_CONTA_SUPERIOR_NAO_SE_APLICA]:Verifica, caso o nível da conta – NIVEL (Campo 04) – seja igual “1”, se o código da conta superior – COD_CTA_SUP (Campo 06) – não foi informado. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n [REGRA_CTA_CONSOLIDADA_DE_NIVEL_SUPERIOR_INVALIDA]:Verifica se o nível da conta –\r\nNÍVEL (Campo 04) – é maior que 1. Se afirmativo verifica as seguintes regras:\r\nREGRA_CODIGO_CONTA_NIVEL_SUPERIOR_INVALIDO: Verifica se o código da conta\r\nsuperior – COD_CTA_SUP (Campo 06) – existe no plano de contas (registro K200).\r\nREGRA_CONTA_NIVEL_SUPERIOR_NAO_S', 3, '1:N', '[COD_CTA]', NULL),
(7, '07', 'CTA', 'Nome da conta.', 'C', NULL, NULL, NULL, 1, NULL, 3, '1:N', '[COD_CTA]', NULL);

