(1, '01', 'REG', 'Texto fixo contendo \"K210\".', 'C', '004', NULL, '\"K210\"', 1, NULL, 4, '1:N', '[COD_EMP] + [COD_CTA_EMP]\r\n', '[REGRA_CONTA_CONSOLIDADA_ANALITICA]: Verifica se a conta consolidada é analítica no registro K200 (indicador do tipo de contas – IND_CTA – Campo 03 – do registro K200 igual a “A” – Analítica). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n'),
(2, '02', 'COD_EMP', 'Código de identificação da empresa participante.', 'N', '004', NULL, NULL, 1, '[REGRA_EXISTE_EMP_COD_K100]: Verifica se o código de identificação da empresa participante –\r\nCOD_EMP (Campo 02) – foi informado no registro K100, no campo código de identificação da empresa\r\nparticipante – EMP_COD (Campo 03). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n', 4, '1:N', '[COD_EMP] + [COD_CTA_EMP]\r\n', '[REGRA_CONTA_CONSOLIDADA_ANALITICA]: Verifica se a conta consolidada é analítica no registro K200 (indicador do tipo de contas – IND_CTA – Campo 03 – do registro K200 igual a “A” – Analítica). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n'),
(3, '03', 'COD_CTA_EMP', 'Código da conta da empresa participante.', 'C', NULL, NULL, NULL, 1, NULL, 4, '1:N', '[COD_EMP] + [COD_CTA_EMP]\r\n', '[REGRA_CONTA_CONSOLIDADA_ANALITICA]: Verifica se a conta consolidada é analítica no registro K200 (indicador do tipo de contas – IND_CTA – Campo 03 – do registro K200 igual a “A” – Analítica). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n');

