INSERT INTO `bloco_k300` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"K300\".', 'C', '004', NULL, '\"K300\"', 1, NULL, 3, 'O:N', '[COD_CTA]\r\n\r\n', '[REGRA_OBRIGATORIEDADE_K310]: Verifica se existe, pelo menos, um registro K310, quando o valor absoluto das eliminações – VAL_EL (Campo 05) – for maior que zero. Se a regra não for cumprida, o PGE do\r\nSped Contábil gera um erro.\r\n'),
(2, '02', 'COD_CTA', 'Código da conta consolidada.', 'C', NULL, NULL, NULL, 1, '[REGRA_EXISTE_K200_ANALITICA]:Verifica se o código da conta consolidada – COD_CTA (Campo 02)\r\n– existe no registro K200 e se a conta é analítica. Se a regra não for cumprida, o PGE do Sped Contábil gera um\r\nerro.', 3, '0:N', '[COD_CTA]\r\n', '[REGRA_OBRIGATORIEDADE_K310]: Verifica se existe, pelo menos, um registro K310, quando o valor absoluto das eliminações – VAL_EL (Campo 05) – for maior que zero. Se a regra não for cumprida, o PGE do\r\nSped Contábil gera um erro.\r\n'),
(3, '03', 'VAL_AG', 'Valor absoluto aglutinado.', 'N', '019', '02', NULL, 1, NULL, 3, '0:N', '[COD_CTA]\r\n', '[REGRA_OBRIGATORIEDADE_K310]: Verifica se existe, pelo menos, um registro K310, quando o valor absoluto das eliminações – VAL_EL (Campo 05) – for maior que zero. Se a regra não for cumprida, o PGE do\r\nSped Contábil gera um erro.\r\n'),
(4, '04', 'IND_VAL_AG', 'Indicador da situação do valor aglutinado: D – Devedor; C – Credor.', 'C', '001', NULL, '[D;C]', 1, NULL, 3, '0:N', '[COD_CTA]\r\n', '[REGRA_OBRIGATORIEDADE_K310]: Verifica se existe, pelo menos, um registro K310, quando o valor absoluto das eliminações – VAL_EL (Campo 05) – for maior que zero. Se a regra não for cumprida, o PGE do\r\nSped Contábil gera um erro.\r\n'),
(5, '05', 'VAL_EL', 'Valor absoluto das eliminações.', 'N', '019', '02', NULL, 1, '[REGRA_SOMATORIO_VALOR_ELIMINACOES]:Verifica se o valor absoluto das eliminações –\r\nVAL_EL (Campo 05) – é igual ao somatório das parcelas do valor eliminado total – VALOR (Campo 03) – do registro K310, considerando o indicador da situação do saldo (devedor ou credor). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '0:N', '[COD_CTA]\r\n', '[REGRA_OBRIGATORIEDADE_K310]: Verifica se existe, pelo menos, um registro K310, quando o valor absoluto das eliminações – VAL_EL (Campo 05) – for maior que zero. Se a regra não for cumprida, o PGE do\r\nSped Contábil gera um erro.\r\n'),
(6, '06', 'IND_VAL_EL', 'Indicador da situação do valor eliminado: D – Devedor; C – Credor.', 'C', '001', NULL, '[D;C]', 1, NULL, 3, '0:N', '[COD_CTA]\r\n', '[REGRA_OBRIGATORIEDADE_K310]: Verifica se existe, pelo menos, um registro K310, quando o valor absoluto das eliminações – VAL_EL (Campo 05) – for maior que zero. Se a regra não for cumprida, o PGE do\r\nSped Contábil gera um erro.\r\n'),
(7, '07', 'VAL_CS', 'Valor absoluto consolidado: VAL_CS = VAL_AG - VAL_EL.', 'N', '019', '02', NULL, 1, '[REGRA_CALCULO_VALOR_CONSOLIDADO]:Verifica se o valor absoluto consolidado – VAL_CS\r\n(Campo 08) – é igual ao resultado da diferença entre o valor absoluto aglutinado – VAL_AG (Campo 03) – e o valor absoluto das eliminações – VAL_EL (Campo 05) –, considerando os indicadores da situação do saldo(devedor ou credor). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 3, '0:N', '[COD_CTA]\r\n', '[REGRA_OBRIGATORIEDADE_K310]: Verifica se existe, pelo menos, um registro K310, quando o valor absoluto das eliminações – VAL_EL (Campo 05) – for maior que zero. Se a regra não for cumprida, o PGE do\r\nSped Contábil gera um erro.\r\n'),
(8, '08', 'IND_VAL_CS', 'Indicador da situação do valor consolidado: D – Devedor; C – Credor.', 'C', '001', NULL, '[D;C]', 1, NULL, 3, '0:N', '[COD_CTA]\r\n', '[REGRA_OBRIGATORIEDADE_K310]: Verifica se existe, pelo menos, um registro K310, quando o valor absoluto das eliminações – VAL_EL (Campo 05) – for maior que zero. Se a regra não for cumprida, o PGE do\r\nSped Contábil gera um erro.\r\n');

