(2, '02', 'EMP_COD_PARTE', 'Código da empresa detentora do valor aglutinado que foi eliminado.', 'N', '004', NULL, NULL, 1, '[REGRA_EXISTE_EMP_COD_K100]:Verifica se o código da empresa detentora do valor aglutinado que foi\r\neliminado – EMP_COD_PART (Campo 02) – foi informado no registro K100, no campo código de identificação\r\nda empresa participante – EMP_COD (Campo 03). Se a regra não for cumprida, o PGE do Sped Contábil gera\r\num erro.\r\n', 4, '0:N', '[EMP_COD_PARTE]\r\n', NULL),
(3, '03', 'VALOR', 'Parcela do valor eliminado total.', 'N', '019', '02', NULL, 1, '[REGRA_SOMATORIO_VALOR_CONTRAPARTIDA]:Verifica se o somatório do valor eliminado total –\r\nVALOR (Campo 03) do registro K310 com a contrapartida do valor total eliminado – VALOR (Campo 04) – doregistro K315 é igual a zero, considerando os indicadores de situação do valor eliminado (D – Devedor ou C –Credor). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 4, '0:N', '[EMP_COD_PARTE]\r\n', NULL),
(4, '04', 'IND_VALOR', 'Indicador da situação do valor eliminado: D – Devedor; C – Credor.', 'C', '001', NULL, '[D;C]', 1, NULL, 4, '0:N', '[EMP_COD_PARTE]\r\n', NULL);

