INSERT INTO `bloco_k315` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"K315\".', 'C', '004', NULL, '\"K315\"', 1, NULL, 5, '0:N', '[EMP_COD_CONTRA] + [COD_CONTRA]', NULL),
(2, '02', 'EMP_COD_CONTRA', 'Código da empresa da contrapartida.', 'N', '004', NULL, NULL, 1, '[REGRA_EXISTE_EMP_COD_K100]:Verifica se o código da empresa da contrapartida – EMP_COD_CONTRA (Campo 02) – foi informado no registro K100, no campo código de identificação da empresa participante – EMP_COD (Campo 03). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n\r\n[REGRA_EMP_COD_CONTRA_DIFERENTE_EMP_COD_PARTE]:\r\nVerifica se o código da empresa da contrapartida – EMP_COD_CONTRA (Campo 02) – é diferente do código da empresa detentora do valor aglutinado que foi eliminado – EMP_COD_PARTE (Campo 02) – informado no registro K310. Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso.', 5, '0:N', '[EMP_COD_CONTRA] + [COD_CONTRA]', NULL),
(3, '03', 'COD_CONTRA', 'Código da conta consolidada da contrapartida.', 'C', NULL, NULL, NULL, 1, '[REGRA_COD_CTA_DIFERENTE_COD_CONTRA]:  Verifica se o código da conta consolidada da contrapartida – COD_CONTRA (Campo 03) – é diferente do código da conta consolidada – COD_CTA (Campo 02) – informado no registro K300. Se a regra não for cumprida, o PGE do Sped Contábil gera um aviso. [REGRA_EXISTE_COD_CTA_K300]:Verifica se o código da conta consolidada da contrapartida –\r\nCOD_CONTRA (Campo 03) – existe em algum dos registros K300 existentes, no campo código da conta\r\nconsolidada – COD_CAT (Campo 02). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 5, '0:N', '[EMP_COD_CONTRA] + [COD_CONTRA]', NULL),
(4, '04', 'VALOR', 'Parcela da contrapartida do valor eliminado total.', 'N', '019', '02', NULL, 1, '[REGRA_MAIOR_QUE_ZERO]: Verifica se a parcela da contrapartida do valor eliminado total – VALOR\r\n(Campo 04) – é maior que zero. Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.\r\n [REGRA_SOMATORIO_VALOR_CONTRAPARTIDA]:Verifica se o somatório do valor eliminado total –\r\nVALOR (Campo 03) do registro K310 com a contrapartida do valor total eliminado – VALOR (Campo 04) – do registro K315 é igual a zero, considerando os indicadores de situação do valor eliminado (D – Devedor ou C –Credor). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.', 5, '0:N', '[EMP_COD_CONTRA] + [COD_CONTRA]', NULL),
(5, '05', 'IND_VALOR', 'Indicador da situação do valor eliminado: D – Devedor; C – Credor.', 'C', '001', NULL, '[D;C]', 1, NULL, 5, '0:N', '[EMP_COD_CONTRA] + [COD_CONTRA]', NULL);

