INSERT INTO `bloco_k990` (`id`, `num`, `campo`, `descricao`, `tipo`, `tamanho`, `decimal`, `valores_validos`, `obrigatorio`, `regras_validacao`, `nivel_hierarquico`, `ocorrencia`, `campos_chave`, `regras_registro`) VALUES
(1, '01', 'REG', 'Texto fixo contendo \"K990\".', 'C', '004', NULL, '\"K990\"', 1, NULL, 1, '1:1', '[REG]\r\n', '[REGRA_OCORRENCIA_UNITARIA_ARQ]: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “K990” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.'),
(2, '02', 'QTD_LIN_K', 'Quantidade total de linhas do Bloco K.', 'N', NULL, NULL, NULL, 1, '[REGRA_QRD_LIN_BLOCOK]:Verifica se número de linhas do bloco K é igual à quantidade de linha do\r\nbloco K informada no campo – QTD_LIN (Campo 02).', 1, '1:1', '[REG]\r\n', '[REGRA_OCORRENCIA_UNITARIA_ARQ]: Verifica se o registro ocorreu apenas uma vez por arquivo, considerando a chave “K990” (REG). Se a regra não for cumprida, o PGE do Sped Contábil gera um erro.');
